package com.improvedlooting;

import java.awt.*;
import java.awt.event.*;
import java.util.Objects;
import javax.swing.*;
import javax.swing.event.*;
import javax.swing.undo.UndoManager;

/** Draft-based editor: compiling and closing never replace the active filter. */
final class FilterEditor
{
    private final ItemIcons icons;
    private final JTextArea source = new JTextArea();
    private final JTextArea status = new JTextArea(3, 50);
    private final JButton save = new JButton("Save filter");
    private final JButton validate = new JButton("Check draft");
    private JDialog dialog;
    private Object profile;
    private String originalBackup, savedSource;
    private FilterIcons.Bundle original=new FilterIcons.Bundle();
    private FilterIcons.Prepared checked;
    private int revision;
    private boolean closed;
    private String seedName;
    void seedName(String name) { seedName=name; }
    private ItemPicker itemPicker;
    private IconPalette iconPalette;
    private RuleOptions options;

    FilterEditor(ItemIcons icons) { this.icons = icons; }

    void open(Component owner)
    {
        profile = icons.configs.getProfile();
        originalBackup = icons.filters.export();
        original = originalBackup.isBlank() ? new FilterIcons.Bundle() : icons.gson.fromJson(originalBackup, FilterIcons.Bundle.class);
        savedSource = originalBackup.isBlank() ? "" : FilterIcons.source(original);
        source.setText(savedSource);
        source.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 13));
        source.setTabSize(4);
        UndoManager undo = new UndoManager();
        source.getDocument().addUndoableEditListener(undo);
        source.getInputMap().put(KeyStroke.getKeyStroke("control Z"), "undoDraft");
        source.getActionMap().put("undoDraft", new AbstractAction() { public void actionPerformed(ActionEvent e) { if (undo.canUndo()) undo.undo(); } });
        source.getInputMap().put(KeyStroke.getKeyStroke("control Y"), "redoDraft");
        source.getActionMap().put("redoDraft", new AbstractAction() { public void actionPerformed(ActionEvent e) { if (undo.canRedo()) undo.redo(); } });
        source.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { changed(); }
            public void removeUpdate(DocumentEvent e) { changed(); }
            public void changedUpdate(DocumentEvent e) { changed(); }
        });
        JPanel root = new JPanel(new BorderLayout(12, 12));
        root.setBorder(BorderFactory.createEmptyBorder(16, 16, 16, 16));
        root.add(new JLabel("<html><b>Filter editor</b><br>Changes stay in this draft until you check and save. Existing image files are retained.</html>"), BorderLayout.NORTH);
        JTabbedPane tabs = new JTabbedPane();
        tabs.addTab("Build a rule", builder(tabs));
        JPanel advanced = new JPanel(new BorderLayout(8, 8));
        advanced.add(new JLabel("Full Filterscape script • Ctrl+Z undo • Ctrl+Y redo • copy all to export"), BorderLayout.NORTH);
        advanced.add(new JScrollPane(source), BorderLayout.CENTER);
        tabs.addTab("Advanced script", advanced);
        root.add(tabs, BorderLayout.CENTER);
        JPanel footer = new JPanel(new BorderLayout(8, 8));
        status.setEditable(false); status.setLineWrap(true); status.setWrapStyleWord(true); status.setOpaque(false);
        status.setText("Rules control ground labels and icons. Appearance and Alerts are in the Improved Looting side panel.");
        footer.add(new JScrollPane(status), BorderLayout.CENTER);
        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        JButton cancel = new JButton("Close"); cancel.addActionListener(e -> requestClose());
        validate.addActionListener(e -> check()); save.setEnabled(false); save.addActionListener(e -> save());
        actions.add(cancel); actions.add(validate); actions.add(save); footer.add(actions, BorderLayout.SOUTH);
        root.add(footer, BorderLayout.SOUTH);
        dialog = new JDialog(SwingUtilities.getWindowAncestor(owner), "Filter editor — Improved Looting", Dialog.ModalityType.MODELESS);
        dialog.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
        dialog.addWindowListener(new WindowAdapter() { public void windowClosing(WindowEvent e) { requestClose(); } });
        dialog.setContentPane(root); dialog.setMinimumSize(new Dimension(660, 580)); dialog.setSize(900, 760);
        dialog.setLocationRelativeTo(owner); dialog.setVisible(true);
    }

    JPanel builder(JTabbedPane tabs)
    {
        JPanel body=new JPanel(new BorderLayout(10,10));
        body.setBorder(BorderFactory.createEmptyBorder(8,4,8,4));
        JTextArea explanation=new JTextArea("Find an item, choose an icon, then add the rule to your draft. You can still type a wildcard pattern such as *potion*. Earlier matching rules take priority.");
        explanation.setPreferredSize(new Dimension(400,36));
        explanation.setRows(2); explanation.setLineWrap(true); explanation.setWrapStyleWord(true); explanation.setEditable(false); explanation.setOpaque(false);
        body.add(explanation,BorderLayout.NORTH);
        itemPicker=new ItemPicker(icons.search);
        iconPalette=new IconPalette(icons,original.images);
        itemPicker.onSelect(iconPalette::currentItem);
        if(seedName!=null)itemPicker.value(seedName);
        JPanel match=new JPanel(new BorderLayout()); match.setBorder(BorderFactory.createTitledBorder("1. Find the item")); match.add(itemPicker,BorderLayout.NORTH);
        JPanel visual=new JPanel(new BorderLayout()); visual.setBorder(BorderFactory.createTitledBorder("2. Choose its icon")); visual.add(iconPalette,BorderLayout.CENTER);
        JPanel columns=new JPanel(new GridLayout(1,2,10,0)); columns.add(match); columns.add(visual);
        body.add(columns,BorderLayout.CENTER);
        JPanel actions=new JPanel(new BorderLayout(8,8));
        JComboBox<String> position=new JComboBox<>(new String[]{"Before existing rules (higher priority)","After existing rules (fallback)"});
        if(original.sounds==null)original.sounds=new java.util.LinkedHashMap<>();
        options=new RuleOptions(icons,original.sounds);
        JPanel choices=new JPanel(new BorderLayout(5,5));choices.add(options,BorderLayout.CENTER);choices.add(position,BorderLayout.SOUTH);
        actions.add(choices,BorderLayout.NORTH);
        JButton add=new JButton("Add to draft and review");
        add.addActionListener(e -> {
            try {
                IconPalette.Selection choice=iconPalette.selection();
                String rule=options.apply(rule(itemPicker.value(),choice));
                if(choice.image!=null) {
                    String existing=original.images.get(choice.file);
                    if(existing!=null && !existing.equals(choice.image)) throw new IllegalArgumentException("An existing image uses that filename. Choose a different icon.");
                    original.images.put(choice.file,choice.image);
                }
                String text=source.getText();
                source.setText(position.getSelectedIndex()==0?rule+"\n"+text:text+"\n"+rule);
                tabs.setSelectedIndex(1); source.setCaretPosition(position.getSelectedIndex()==0?0:source.getDocument().getLength());
            } catch(IllegalArgumentException ex) { status.setText(ex.getMessage()); }
        });
        actions.add(add,BorderLayout.SOUTH); body.add(actions,BorderLayout.SOUTH);
        return body;
    }

    static String rule(String name,IconPalette.Selection selection)
    {
        if(selection.kind==null) return rule(name,2,0);
        return rule(name,0,0).replace("icon=CurrentItem();","icon="+selection.expression()+";");
    }

    static String rule(String name, int effect, int item)
    {
        name = name.trim();
        if (name.isEmpty() || name.length() > 200 || name.indexOf('"') >= 0 || name.indexOf('\\') >= 0 || name.chars().anyMatch(Character::isISOControl))
            throw new IllegalArgumentException("Enter an item name without quotes, backslashes or line breaks (up to 200 characters).");
        if (effect < 0 || effect > 2 || item < 0 || item > 100000) throw new IllegalArgumentException("Invalid icon choice.");
        String display = effect == 2 ? "hideOverlay=true;" : "hidden=false; hideOverlay=false; icon=" + (effect == 0 ? "CurrentItem()" : "Item(" + item + ")") + ";";
        return "rule(name:\"" + name + "\") { " + display + " }\n";
    }

    private void changed() { revision++; checked = null; save.setEnabled(false); status.setText("Draft changed. Check it before saving; your active filter is unchanged."); }
    private boolean contextValid()
    {
        if (closed) return false;
        if (!Objects.equals(profile, icons.configs.getProfile()) || !Objects.equals(originalBackup, icons.filters.export())) {
            checked = null; save.setEnabled(false); status.setText("The profile or active filter changed elsewhere. Copy your draft, then reopen the editor to avoid overwriting those changes."); return false;
        }
        return true;
    }
    private void check()
    {
        if (!contextValid()) return;
        final int version = revision;
        FilterIcons.Bundle draft = new FilterIcons.Bundle(); draft.compressedSource = FilterIcons.compress(source.getText()); draft.images.putAll(original.images);
        if (original.sounds != null) draft.sounds.putAll(original.sounds);
        validate.setEnabled(false); save.setEnabled(false); status.setText("Checking script and image references…");
        new SwingWorker<FilterIcons.Prepared, Void>() {
            protected FilterIcons.Prepared doInBackground() { return icons.filters.prepare(draft); }
            protected void done() {
                validate.setEnabled(true);
                if (!contextValid() || revision != version) return;
                try { checked = get(); save.setEnabled(true); status.setText("Ready to save: " + checked.program.rules.size() + " rules, " + checked.images.size() + " referenced images. Your previous filter will be available through Undo filter import."); }
                catch (Exception e) { checked = null; status.setText("Not saved. " + (e.getCause() == null ? e.getMessage() : e.getCause().getMessage())); }
            }
        }.execute();
    }
    private void save()
    {
        if (!contextValid() || checked == null) return;
        icons.filters.save(checked); originalBackup = icons.filters.export(); original = checked.bundle; savedSource = source.getText();
        save.setEnabled(false); status.setText("Filter saved. Ground display follows your Appearance settings. Connected menu icons use Improved Right-Clicks.");
    }
    private void requestClose()
    {
        if (!source.getText().equals(savedSource) && JOptionPane.showConfirmDialog(dialog, "Discard unsaved changes?", "Close filter editor", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) return;
        close();
    }
    void close() { closed = true; if(options!=null)options.close(); if(itemPicker!=null) itemPicker.close(); if(iconPalette!=null) iconPalette.close(); if (dialog != null) dialog.dispose(); }
    boolean isOpen() { return dialog != null && dialog.isDisplayable(); }
    void focus() { dialog.toFront(); }
}

package com.improvedlooting;
import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import com.improvedlooting.rs2f.LootFilter;
import com.improvedlooting.rs2f.model.*;
@Singleton
class FilterIcons {
 static final String KEY="lootIconFilter",BACKUP="lootIconFilterBackup";
 @Inject java.util.concurrent.ScheduledExecutorService executor;
 @Inject ConfigManager configs; @Inject Gson gson; @Inject Client client; @Inject ItemManager items;
 static final class Bundle { int version=1; String compressedSource; Map<String,String> images=new LinkedHashMap<>(); Map<String,String> sounds=new LinkedHashMap<>(); }
 static final class Prepared { Bundle bundle; LootFilter program;
  private static final int PREAMBLE_LINES=LootFilter.preambleLines();
  int userLine(int line) { return Math.max(1,line-PREAMBLE_LINES); } Map<String,BufferedImage> images=new LinkedHashMap<>(); Map<String,byte[]> sounds=new LinkedHashMap<>(); }
 private volatile Prepared current;
 private String loaded;
 private long generation;
 private Object profile;
 private volatile String loadStatus="No imported filter active";
 static String compress(String source) {
  try { ByteArrayOutputStream out=new ByteArrayOutputStream(); try(GZIPOutputStream gzip=new GZIPOutputStream(out)) { gzip.write(source.getBytes(StandardCharsets.UTF_8)); } return Base64.getEncoder().encodeToString(out.toByteArray()); }
  catch(IOException e) { throw new IllegalArgumentException("Cannot package filter",e); }
 }
 static String source(Bundle bundle) {
  if(bundle==null || bundle.version!=1 || bundle.compressedSource==null || bundle.compressedSource.length()>1500000) throw new IllegalArgumentException("Invalid filter backup");
  try(GZIPInputStream in=new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(bundle.compressedSource)))) {
   byte[] data=in.readNBytes(1000001); if(data.length>1000000) throw new IllegalArgumentException("Filter exceeds 1 MB"); return new String(data,StandardCharsets.UTF_8);
  } catch(IOException e) { throw new IllegalArgumentException("Invalid filter archive",e); }
 }
 Prepared prepare(Bundle bundle) {
  Prepared p=new Prepared(); p.bundle=bundle; p.program=LootFilter.compile(source(bundle));
  if(bundle.images==null || bundle.images.size()>128) throw new IllegalArgumentException("Use at most 128 images");
  long pixels=0,encodedImages=0;
  for(Map.Entry<String,String> asset:bundle.images.entrySet()) {
   String file=asset.getKey();
   IconImages.safeName(file); String encoded=bundle.images.get(file);
   if(encoded==null) throw new IllegalArgumentException("Missing image: "+file);
   BufferedImage image=IconImages.decode(encoded); pixels+=(long)image.getWidth()*image.getHeight(); encodedImages+=encoded.length();
   if(pixels>16000000 || encodedImages>6000000) throw new IllegalArgumentException("Images exceed the combined 16-million-pixel / 6 MB limit");
   p.images.put(file,image);
  }
  for(String file:p.program.files())if(!p.images.containsKey(file))throw new IllegalArgumentException("Missing image: "+file);
  if(bundle.sounds==null) bundle.sounds=new LinkedHashMap<>();
  if(bundle.sounds.size()>32) throw new IllegalArgumentException("Use at most 32 sound files");
  long total=0;
  for(Map.Entry<String,String> sound:bundle.sounds.entrySet()) {
   IconImages.safeName(sound.getKey()); byte[] data=FilterSounds.decode(sound.getValue()); total+=data.length;
   if(total>4000000) throw new IllegalArgumentException("Sound files exceed 4 MB combined");
   p.sounds.put(sound.getKey(),data);
  }
  long packed=bundle.compressedSource.length()+encodedImages;
  for(String sound:bundle.sounds.values())packed+=sound.length();
  if(packed>8700000)throw new IllegalArgumentException("Combined filter assets exceed the portable backup limit");
  for(com.improvedlooting.rs2f.FilterRule rule:p.program.rules) { com.improvedlooting.rs2f.model.SoundProvider sound=rule.getDisplay().toBuilder().hidden(false).build().getSound();if(sound!=null && sound.getFile()!=null && !p.sounds.containsKey(sound.getFile()))throw new IllegalArgumentException("Missing sound: "+sound.getFile()); }
  return p;
 }
 Prepared parse(String json) {
  if(json.length()>9000000) throw new IllegalArgumentException("Filter backup exceeds 9 MB");
  try { return prepare(gson.fromJson(json,Bundle.class)); } catch(com.google.gson.JsonParseException e) { throw new IllegalArgumentException("Invalid filter backup",e); }
 }
 synchronized void reload() {
  String raw=configs.getConfiguration(ImprovedLootingConfig.GROUP,KEY);
  Object nextProfile=configs.getProfile();
  if(current!=null && Objects.equals(raw,loaded) && Objects.equals(profile,nextProfile)) return;
  profile=nextProfile; long token=++generation;
  loaded=raw; current=null;
  if(raw==null || raw.isBlank()) {
   Bundle defaults=new Bundle(); defaults.compressedSource=compress("apply(true) {showValue=true; showDespawn=true;}");
   current=prepare(defaults); loadStatus="Default visible labels"; return;
  }
  loadStatus="Loading imported filter...";
  executor.execute(() -> {
   Prepared next=null; String status="No imported filter active";
   try { next=parse(raw); } catch(IllegalArgumentException e) { status="Imported filter could not load; re-import its backup."; }
   synchronized(FilterIcons.this) { if(token==generation && Objects.equals(nextProfile,configs.getProfile())) { current=next; loadStatus=status; } }
  });
 }
 synchronized void save(Prepared p) {
  generation++; profile=configs.getProfile();
  String before=configs.getConfiguration(ImprovedLootingConfig.GROUP,KEY);
  configs.setConfiguration(ImprovedLootingConfig.GROUP,BACKUP,before==null ? "" : before);
  String raw=p==null ? "" : gson.toJson(p.bundle);
  current=p; loaded=raw; loadStatus="No imported filter active"; configs.setConfiguration(ImprovedLootingConfig.GROUP,KEY,raw); if(p==null) reload();
 }
 void undo() { String raw=configs.getConfiguration(ImprovedLootingConfig.GROUP,BACKUP); if(raw!=null) save(raw.isBlank() ? null : parse(raw)); }
 String export() { String raw=configs.getConfiguration(ImprovedLootingConfig.GROUP,KEY); return raw==null ? "" : raw; }
 String status() { Prepared p=current; return p==null ? loadStatus : p.program.rules.size()+" imported rules; "+p.images.size()+" embedded images"; }
 Prepared snapshot() { return current; }
 ItemFacts facts(Tile tile,TileItem item) {
  ItemComposition c=items.getItemComposition(item.getId());
  ItemComposition note=c.getLinkedNoteId()<0 ? null : items.getItemComposition(c.getLinkedNoteId());
  long price=item.getId()==995 ? 1 : item.getId()==13204 ? 1000 : items.getItemPrice(item.getId());
  return ItemFacts.builder().id(item.getId()).name(c.getName()).quantity(item.getQuantity()).ownership(item.getOwnership())
   .accountType(client.getVarbitValue(VarbitID.IRONMAN)).gePrice(price).haPrice(c.getHaPrice()).stackable(c.isStackable()).noted(c.getNote()!=-1)
   .tradeable(c.isTradeable() || note!=null && note.isTradeable()).geTradeable(c.isGeTradeable() || note!=null && note.isGeTradeable())
   .worldPoint(WorldPoint.fromLocalInstance(client,tile.getLocalLocation())).build();
 }
 ItemIcons.Assignment find(MenuEntry entry) {
  Prepared p=current; if(p==null) return null;
  WorldView view=client.getWorldView(entry.getWorldViewId()); if(view==null) return null;
  int x=entry.getParam0(),y=entry.getParam1(),plane=view.getPlane(); Tile[][][] tiles=view.getScene().getTiles();
  if(plane<0 || plane>=tiles.length || x<0 || x>=tiles[plane].length || y<0 || y>=tiles[plane][x].length) return null;
  Tile tile=tiles[plane][x][y]; if(tile==null || tile.getGroundItems()==null) return null;
  BufferedImageProvider chosen=null; boolean found=false;
  for(TileItem item:tile.getGroundItems()) {
   if(item.getId()!=entry.getIdentifier()) continue;
   ItemFacts facts=facts(tile,item);
   BufferedImageProvider icon=p.program.find(facts);
   if(found && !Objects.equals(chosen,icon)) return null; // Menu cannot distinguish ambiguous stacks.
   chosen=icon; found=true;
  }
  if(chosen==null) return null;
  ItemIcons.Assignment a=new ItemIcons.Assignment(); a.itemId=entry.getIdentifier();
  if(chosen instanceof BufferedImageProvider.CurrentItem) a.kind=ItemIcons.Kind.CURRENT_ITEM;
  else if(chosen instanceof BufferedImageProvider.Item) { a.kind=ItemIcons.Kind.ITEM; a.iconId=((BufferedImageProvider.Item)chosen).getItemId(); if(a.iconId>=client.getItemCount()) return null; }
  else if(chosen instanceof BufferedImageProvider.Sprite) { a.kind=ItemIcons.Kind.SPRITE; a.iconId=((BufferedImageProvider.Sprite)chosen).getSpriteId(); if(a.iconId==9000000) return null; a.spriteIndex=((BufferedImageProvider.Sprite)chosen).getIndex(); }
  else { a.kind=ItemIcons.Kind.IMAGE; a.image=p.bundle.images.get(((BufferedImageProvider.File)chosen).getFilename()); }
  return a;
 }
}

package com.improvedlooting;

import java.io.*;
import java.util.Base64;
import net.runelite.client.util.Filepath;

/** Bounded, explicitly imported audio assets; no paths are opened during gameplay. */
final class FilterSounds
{
    static byte[] decode(String encoded)
    {
        if (encoded == null || encoded.length() > 1400000) throw new IllegalArgumentException("Sound exceeds 1 MB");
        byte[] bytes = Base64.getDecoder().decode(encoded);
        validate(bytes); return bytes;
    }
    static String read(Filepath path) throws IOException
    {
        try (InputStream in = path.openInputStream()) {
            byte[] bytes = in.readNBytes(1000001); validate(bytes); return Base64.getEncoder().encodeToString(bytes);
        }
    }
    private static void validate(byte[] bytes)
    {
        if (bytes.length > 1000000) throw new IllegalArgumentException("Sound exceeds 1 MB");
        // Inspect bounded container metadata only. RuneLite AudioPlayer owns all
        // decoding and playback; importing a file never opens an audio device.
        if (id(bytes, 0, "RIFF") && id(bytes, 8, "WAVE")) wave(bytes);
        else if (id(bytes, 0, "FORM") && (id(bytes, 8, "AIFF") || id(bytes, 8, "AIFC"))) aiff(bytes);
        else if (id(bytes, 0, ".snd")) au(bytes);
        else throw unsupported();
    }

    private static void wave(byte[] b)
    {
        int end = containerEnd(b, true), channels = 0, frameSize = 0;
        long rate = 0, dataSize = -1;
        boolean format = false;
        for (int at = 12; at < end;)
        {
            int size = chunkSize(b, at, end, true), body = at + 8;
            if (id(b, at, "fmt "))
            {
                if (format || size < 16) throw unsupported();
                format = true;
                int code = u16(b, body, true), bits = u16(b, body + 14, true);
                channels = u16(b, body + 2, true);
                rate = u32(b, body + 4, true);
                frameSize = u16(b, body + 12, true);
                if (code == 0xfffe)
                {
                    // WAVE_FORMAT_EXTENSIBLE's standard PCM/float GUID tail.
                    if (size < 40 || u16(b, body + 16, true) < 22
                        || u32(b, body + 26, true) != 0 || u16(b, body + 30, true) != 0x10
                        || u32(b, body + 32, false) != 0x800000aaL
                        || u32(b, body + 36, false) != 0x00389b71L) throw unsupported();
                    code = u16(b, body + 24, true);
                }
                boolean pcm = code == 1 && bits >= 8 && bits <= 32 && bits % 8 == 0;
                boolean floating = code == 3 && (bits == 32 || bits == 64);
                boolean companded = (code == 6 || code == 7) && bits == 8;
                if (!(pcm || floating || companded) || frameSize != channels * (bits / 8)
                    || u32(b, body + 8, true) != rate * frameSize) throw unsupported();
            }
            else if (id(b, at, "data"))
            {
                if (!format || dataSize >= 0) throw unsupported();
                dataSize = size;
            }
            at = body + size + (size & 1);
        }
        limits(channels, rate, frameSize, dataSize);
    }

    private static void aiff(byte[] b)
    {
        int end = containerEnd(b, false), channels = 0, frameSize = 0;
        long frames = -1, dataSize = -1;
        double rate = 0;
        boolean compressed = id(b, 8, "AIFC"), format = false;
        for (int at = 12; at < end;)
        {
            int size = chunkSize(b, at, end, false), body = at + 8;
            if (id(b, at, "COMM"))
            {
                if (format || size < (compressed ? 22 : 18)) throw unsupported();
                format = true;
                channels = u16(b, body, false);
                frames = u32(b, body + 2, false);
                int bits = u16(b, body + 6, false), exponent = u16(b, body + 8, false);
                if ((exponent & 0x8000) != 0 || exponent == 0 || exponent == 0x7fff) throw unsupported();
                rate = Math.scalb(u32(b, body + 10, false) * 4294967296.0
                    + u32(b, body + 14, false), exponent - 16383 - 63);
                boolean pcm = !compressed || id(b, body + 18, "NONE") || id(b, body + 18, "sowt");
                boolean companded = compressed && (id(b, body + 18, "ulaw") || id(b, body + 18, "alaw"));
                if (pcm && bits >= 1 && bits <= 32) frameSize = channels * ((bits + 7) / 8);
                else if (companded) frameSize = channels;
                else throw unsupported();
            }
            else if (id(b, at, "SSND"))
            {
                if (dataSize >= 0 || size < 8) throw unsupported();
                long offset = u32(b, body, false);
                if (offset > size - 8) throw unsupported();
                dataSize = size - 8 - offset;
            }
            at = body + size + (size & 1);
        }
        limits(channels, rate, frameSize, dataSize);
        if (!format || frames < 0 || frames * frameSize > dataSize || frames > rate * 15) throw unsupported();
    }

    private static void au(byte[] b)
    {
        if (b.length < 24) throw unsupported();
        long offset = u32(b, 4, false), dataSize = u32(b, 8, false);
        long encoding = u32(b, 12, false), rate = u32(b, 16, false), channels = u32(b, 20, false);
        int sampleBytes;
        if (encoding == 1 || encoding == 2 || encoding == 27) sampleBytes = 1;
        else if (encoding >= 3 && encoding <= 5) sampleBytes = (int)encoding - 1;
        else if (encoding == 6) sampleBytes = 4;
        else throw unsupported();
        if (offset < 24 || offset > b.length || dataSize > b.length - offset || channels > 2) throw unsupported();
        limits((int)channels, rate, (int)channels * sampleBytes, dataSize);
    }

    private static void limits(int channels, double rate, int frameSize, long dataSize)
    {
        if (channels < 1 || channels > 2 || !Double.isFinite(rate) || rate <= 0 || rate > 96000
            || frameSize <= 0 || dataSize < 0 || dataSize % frameSize != 0
            || dataSize / frameSize > rate * 15)
            throw new IllegalArgumentException("Use sounds of at most 15 seconds, stereo and 96 kHz");
    }

    private static int containerEnd(byte[] b, boolean little)
    {
        if (b.length < 12) throw unsupported();
        long size = u32(b, 4, little);
        if (size < 4 || size > b.length - 8) throw unsupported();
        return (int)size + 8;
    }

    private static int chunkSize(byte[] b, int at, int end, boolean little)
    {
        if (end - at < 8) throw unsupported();
        long size = u32(b, at + 4, little);
        if (size + (size & 1) > end - at - 8) throw unsupported();
        return (int)size;
    }

    private static boolean id(byte[] b, int at, String value)
    {
