                Rectangle collapsed=LootCardPainter.place(layoutX,anchor.getY(),width,baseHeight,viewport,occupied);
                if(collapsed==null){overflow+=entries.size();continue;}
                boolean hover=collapsed.contains(pointer)||(tile==previous&&previousBounds!=null&&previousBounds.contains(pointer));
                int count=Math.min(Math.min(hover?entries.size():baseCount,fit),Math.max(0,maximum-drawn));if(count==0){overflow+=entries.size();continue;}
                Rectangle box=LootCardPainter.place(layoutX,anchor.getY(),width,count*pitch-(pitch-height)+(entries.size()>count?pitch:0),viewport,occupied);
                if(box==null){count=Math.min(baseCount,maximum-drawn);box=collapsed;}occupied.add(box);
                if(hover){expanded=tile;expandedBounds=box.union(collapsed);}
                if(Math.abs(box.x+width/2-anchor.getX())>10 || Math.abs(box.y+box.height-anchor.getY())>12){g.setColor(new Color(180,190,200,90));g.drawLine(box.x+width/2,box.y+box.height,anchor.getX(),anchor.getY());}
                for(int i=0;i<count;i++){
                    GroundLoot.Entry e=entries.get(i);Rectangle row=new Rectangle(box.x,box.y+i*pitch,width,height);long value=PriceTiers.value(e.facts.getGePrice(),e.renderQuantity);
                    PriceTiers.Tier tier=selected.tiers[PriceTiers.index(selected,value)];g.setFont(tier.bold?bold:plain);
                    Paint rail=LootDisplayOptions.color(config,e,new Color(tier.color));
                    if(LootDisplayOptions.tierEffects(config,e)&&setup!=null){Paint effect=LootTextPaint.paint(tier,selected.seconds,System.nanoTime(),row.x,Math.max(80,width));if(effect!=null)rail=effect;}
                    double fraction=config.iconDespawnFade()?LootCardPainter.remaining(e.renderSpawnTick,e.renderDespawn,now):1;
                    LootCardPainter.row(g,row,rail,image(e,size,fraction),config.lootCompact()?"":e.facts.getName(),e.renderQuantity,LootDisplayOptions.price(config,e),loot.labelHidden(e),config.cardBackground(),config.cardBorder(),config.cardOpacity(),config.cardShortPrices(),seconds(e),theme,backgroundColor);
                    if(input!=null)input.add(row,e,loot.labelHidden(e));
                }
                g.setFont(plain);
                drawn+=count;
                if(entries.size()>count)footer(g,new Rectangle(box.x,box.y+count*pitch,width,height),"+ "+(entries.size()-count)+" more"+(hover?" · Nearby loot":" · hover to expand"));
            }
            if(overflow>0){String text=overflow+" more items · Nearby loot";int summaryWidth=Math.min(viewport.width-8,g.getFontMetrics().stringWidth(text)+16);Rectangle summary=LootCardPainter.place(viewport.x+summaryWidth/2+4,viewport.y+height+4,summaryWidth,height,viewport,occupied);if(summary!=null)footer(g,summary,text);}
        }finally{g.dispose();}
    }
    private int seconds(GroundLoot.Entry entry)
    {
        return LootDisplayOptions.seconds(config,entry,client.getTickCount());
    }
    private void footer(Graphics2D g,Rectangle box,String text)
    {
        LootCardPainter.surface(g,box,config.cardBackground(),config.cardBorder(),config.cardOpacity(),config.cardTheme(),config.cardBackgroundColor());g.setColor(LootCardPainter.VALUE);
        text=LootCardPainter.fit(text,g.getFontMetrics(),box.width-16);
        int x=box.x+(box.width-g.getFontMetrics().stringWidth(text))/2,y=box.y+(box.height-g.getFontMetrics().getHeight())/2+g.getFontMetrics().getAscent();
        if(config.cardTheme()==ImprovedLootingConfig.CardTheme.OSRS){g.setColor(Color.BLACK);g.drawString(text,x+1,y+1);g.setColor(LootCardPainter.VALUE);}
        g.drawString(text,x,y);
    }
}

package com.improvedlooting;

import com.improvedlooting.rs2f.DisplayConfig;
import com.improvedlooting.rs2f.util.TextComponent;
import java.awt.*;
import java.util.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.client.ui.overlay.*;

final class GroundLootOverlay extends Overlay
{
    private final GroundLoot loot;
    private final Client client;
    private final ImprovedLootingConfig config;
    @Inject private PriceTiers tiers;
    @Inject private GroundLootCards groundCards;
    @Inject private LootLabelInput input;
    void clear() { groundCards.clear();if(input!=null)input.reset(); }
    @Inject GroundLootOverlay(GroundLoot loot, Client client, ImprovedLootingConfig config)
    {
        this.loot = loot; this.client = client; this.config = config;
        setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_SCENE);
    }
    @Override public Dimension render(Graphics2D original)
    {
        if(input!=null)input.beginFrame();
        if (!loot.groundAllowed()) return null;
        if (config.groundStyle() == ImprovedLootingConfig.GroundStyle.CARDS) { groundCards.render(original);if(input!=null && !client.isMenuOpen())input.finishFrame();return null; }
        Graphics2D g = (Graphics2D)original.create();
        PriceTiers.Ready tierSetup=tiers!=null?tiers.snapshot():null;
        long animationTime=System.nanoTime();
        try {
            g.clipRect(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
            Map<Tile, Integer> offsets = new IdentityHashMap<>();
            Set<Tile> highlighted = Collections.newSetFromMap(new IdentityHashMap<>());
            int count = 0;
            for (GroundLoot.Entry entry : loot.entries()) {
                if (loot.selected(entry)) {
                    Polygon poly=Perspective.getCanvasTilePoly(client,entry.tile.getLocalLocation());
                    if(poly!=null){g.setColor(new Color(80,220,255,50));g.fill(poly);g.setColor(Color.CYAN);g.draw(poly);}
                }
                if (count >= LootAlerts.clamp(config.maxLabels(),10,1000)) continue;
                DisplayConfig display = entry.display;
                if (entry.grouped || display == null || !loot.inRange(entry, LootAlerts.clamp(config.labelRange(),1,64)) || entry.tile.getItemLayer() == null || loot.labelHidden(entry) && !loot.reveal()) continue;
                if (display.isHighlightTile() && highlighted.add(entry.tile)) {
                    Polygon poly = Perspective.getCanvasTilePoly(client, entry.tile.getLocalLocation());
                    if (poly != null) {
                        if (display.getTileFillColor() != null) { g.setColor(display.getTileFillColor()); g.fill(poly); }
                        g.setColor(display.getTileStrokeColor()); g.draw(poly);
                    }
                }
                g.setFont(config.labelFontSize()==0?display.getFont():display.getFont().deriveFont((float)LootAlerts.clamp(config.labelFontSize(),8,32)));
                PriceTiers.Tier tier=tierSetup==null?null:tierSetup.setup.tiers[PriceTiers.index(tierSetup.setup,PriceTiers.value(entry.facts.getGePrice(),entry.renderQuantity))];
                if(tier!=null && tier.bold)g.setFont(g.getFont().deriveFont(g.getFont().getStyle()|Font.BOLD));
                String text = entry.facts.getName();
                text += LootCardPainter.quantity(entry.renderQuantity);
                String details=LootCardPainter.details(LootDisplayOptions.price(config,entry),config.cardShortPrices(),LootDisplayOptions.seconds(config,entry,client.getTickCount()));
                if(!details.isEmpty())text+=" "+details;
                boolean compact = config.lootCompact();
                if (compact) text = LootCardPainter.quantity(entry.renderQuantity).trim();
                FontMetrics metrics = g.getFontMetrics();
                java.awt.image.BufferedImage image = compact ? lootItemImage(entry) : entry.image;
                int maxIcon=LootAlerts.clamp(config.iconSize(),12,96);
                if(image!=null && config.iconDespawnFade())image=groundCards.image(entry,maxIcon,LootCardPainter.remaining(entry.renderSpawnTick,entry.renderDespawn,loot.renderTick()));
                int iw=0,ih=0;
                if(image!=null){double scale=Math.min((double)maxIcon/image.getWidth(),(double)maxIcon/image.getHeight());if(config.originalImages())scale=Math.min(1,scale);iw=Math.max(1,(int)(image.getWidth()*scale));ih=Math.max(1,(int)(image.getHeight()*scale));}
                int iconWidth = image==null?0:iw+3;
                int height = Math.max(metrics.getHeight(), ih) + 4;
                int width = Math.max(12, metrics.stringWidth(text) + iconWidth + 6);
                net.runelite.api.Point location = Perspective.getCanvasTextLocation(client, g, entry.tile.getLocalLocation(), "", entry.tile.getItemLayer().getHeight() + 20);
                if (location == null) continue;
                int offset = offsets.getOrDefault(entry.tile, 0);
                int x = location.getX() - (config.labelAlignment()==ImprovedLootingConfig.LabelAlignment.LEFT?0:config.labelAlignment()==ImprovedLootingConfig.LabelAlignment.RIGHT?width:width/2), y = location.getY() - offset - height;
                if (y < client.getViewportYOffset() || x < client.getViewportXOffset() || x + width > client.getViewportXOffset() + client.getViewportWidth()) continue;
                count++; offsets.put(entry.tile, offset + height + LootAlerts.clamp(config.labelSpacing(),0,16));
                if (display.getBackgroundColor() != null) { g.setColor(display.getBackgroundColor()); g.fillRect(x, y, width, height); }
                if (display.getBorderColor() != null) { g.setColor(display.getBorderColor()); g.drawRect(x, y, width, height); }
                if (image != null) g.drawImage(image, x + 2, y + (height - ih) / 2, iw, ih, null);
                if(input!=null)input.add(new Rectangle(x,y,width,height),entry,loot.labelHidden(entry));
                Color color=LootDisplayOptions.color(config,entry,tier==null?Color.WHITE:new Color(tier.color));
                TextComponent label = new TextComponent(); label.setText(text); label.setColor(loot.labelHidden(entry) ? Color.GRAY : color);
                if(tier!=null && LootDisplayOptions.tierEffects(config,entry) && !loot.labelHidden(entry)) {
                    label.setForegroundPaint(LootTextPaint.paint(tier,tierSetup.setup.seconds,animationTime,x+iconWidth+3,metrics.stringWidth(text)));
                }
                if (display.getTextAccent() != null) label.setTextAccent(display.getTextAccent());
                if (display.getTextAccentColor() != null) label.setAccentColor(display.getTextAccentColor());
                label.setPosition(new Point(x + iconWidth + 3, y + (height - metrics.getHeight()) / 2 + metrics.getAscent())); label.render(g);
            }
        } finally { g.dispose();if(input!=null && !client.isMenuOpen())input.finishFrame(); }
        return null;
    }
    private java.awt.image.BufferedImage lootItemImage(GroundLoot.Entry entry) { return loot.icons.items.getImage(entry.item.getId()); }
}

package com.improvedlooting;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import javax.imageio.*;
import javax.imageio.stream.MemoryCacheImageInputStream;
import net.runelite.client.util.Filepath;
final class IconImages {
 static String read(Filepath path) throws IOException {
  try(InputStream in=path.openInputStream()) {
   byte[] data=in.readNBytes(2097153);
   if(data.length>2097152) throw new IllegalArgumentException("Image exceeds 2 MB: "+path.getFileName());
   return encode(normalize(data));
  }
 }
 static BufferedImage normalize(byte[] data) throws IOException {
  try(MemoryCacheImageInputStream in=new MemoryCacheImageInputStream(new ByteArrayInputStream(data))) {
   Iterator<ImageReader> readers=ImageIO.getImageReaders(in);
   if(!readers.hasNext()) throw new IllegalArgumentException("Unsupported image. Use PNG, JPEG or GIF.");
   ImageReader r=readers.next();
   try {
    String format=r.getFormatName(); if(!format.equalsIgnoreCase("png") && !format.equalsIgnoreCase("jpeg") && !format.equalsIgnoreCase("gif")) throw new IllegalArgumentException("Use PNG, JPEG or GIF.");
    r.setInput(in); int w=r.getWidth(0),h=r.getHeight(0);
    if(w<1 || h<1 || w>2048 || h>2048 || (long)w*h>4194304) throw new IllegalArgumentException("Image dimensions exceed 2048 x 2048.");
    BufferedImage source=r.read(0),result=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);
    Graphics2D g=result.createGraphics();
    try { g.drawImage(source,0,0,null); } finally { g.dispose(); }
    return result;
   } finally { r.dispose(); }
  }
 }
 static String encode(BufferedImage image) throws IOException { ByteArrayOutputStream out=new ByteArrayOutputStream(); ImageIO.write(image,"png",out); return Base64.getEncoder().encodeToString(out.toByteArray()); }
 static BufferedImage decode(String value) { try { if(value==null || value.length()>2800000) throw new IllegalArgumentException("Invalid saved icon"); return normalize(Base64.getDecoder().decode(value)); } catch(IOException e) { throw new IllegalArgumentException("Invalid saved icon",e); } }
 static String safeName(String name) {
  if(name==null || name.length()>240 || name.isBlank() || name.chars().anyMatch(Character::isISOControl) || name.startsWith("/") || name.startsWith("\\") || name.contains(":")) throw new IllegalArgumentException("Invalid image filename");
  String normalized=name.replace('\\','/');
  for(String part:normalized.split("/",-1)) if(part.equals("..") || part.equals(".") || part.isEmpty()) throw new IllegalArgumentException("Image filename must stay inside the selected icon folder");
  return normalized;
 }
}

package com.improvedlooting;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Map;
import javax.swing.*;

final class IconPalette extends JPanel
{
    static final class Selection
    {
        final ItemIcons.Kind kind;
        final int item;
        final String file, image;
        Selection(ItemIcons.Kind kind,int item,String file,String image) { this.kind=kind; this.item=item; this.file=file; this.image=image; }
        String expression() {
            if(kind==ItemIcons.Kind.CURRENT_ITEM) return "CurrentItem()";
            if(kind==ItemIcons.Kind.ITEM) return "Item("+item+")";
            if(kind==null) return null;
            return "File(\""+file.replace("\\","\\\\").replace("\"","\\\"")+"\")";
        }
    }
    private Selection selected=new Selection(ItemIcons.Kind.CURRENT_ITEM,0,null,null);
    private final JLabel summary=new JLabel("Selected: this item's picture");
    private final ButtonGroup group=new ButtonGroup();
    private final ItemPicker itemPicker;
    private final JToggleButton current;
    private final JToggleButton itemChoice=new JToggleButton("Choose an item picture below");
    private boolean closed;

    IconPalette(ItemIcons icons,Map<String,String> images) { this(icons,images,true); }
    IconPalette(ItemIcons icons,Map<String,String> images,boolean allowHidden)
    {
        super(new BorderLayout(4,4));
        JTabbedPane tabs=new JTabbedPane();
        JPanel common=new JPanel(new GridLayout(0,4,6,6));
        current=tile(common,"This item",null,selected); current.setSelected(true);
        if(allowHidden) tile(common,"Hidden",hiddenImage(),new Selection(null,0,null,null));
        for(ItemIcons.Kind kind:new ItemIcons.Kind[]{ItemIcons.Kind.HEART,ItemIcons.Kind.STAR,ItemIcons.Kind.DIAMOND}) {
            ItemIcons.Assignment assignment=new ItemIcons.Assignment(); assignment.kind=kind;
            BufferedImage image=icons.image(assignment,0);
            String encoded;
            try { encoded=IconImages.encode(image); } catch(IOException ex) { throw new IllegalArgumentException("Could not prepare icon",ex); }
            String name=kind.name().substring(0,1)+kind.name().substring(1).toLowerCase(java.util.Locale.ROOT);
            // Content-derived paths cannot overwrite a user's differently drawn image with the same name.
            String file="improved-icons/"+kind.name().toLowerCase(java.util.Locale.ROOT)+"-"+Integer.toHexString(encoded.hashCode())+".png";
            tile(common,name,image,new Selection(kind,0,file,encoded));
        }
        JPanel commonTop=new JPanel(new BorderLayout()); commonTop.add(common,BorderLayout.NORTH); tabs.addTab("Symbols",commonTop);
        if(!images.isEmpty()) {
            JPanel imported=new JPanel(new GridLayout(0,4,6,6));
            images.forEach((name,encoded) -> tile(imported,name,IconImages.decode(encoded),new Selection(ItemIcons.Kind.IMAGE,0,name,encoded)));
            JScrollPane scroll=new JScrollPane(imported); scroll.setPreferredSize(new Dimension(360,170)); tabs.addTab("Filter images",scroll);
        }
        itemPicker=new ItemPicker(icons.search,3);
        JPanel picture=new JPanel(new BorderLayout(4,4)); picture.add(itemPicker,BorderLayout.CENTER); picture.add(itemChoice,BorderLayout.SOUTH);
        group.add(itemChoice); itemChoice.setEnabled(false);
        itemPicker.onSelect(choice -> {
            itemChoice.setEnabled(choice!=null);
            if(choice!=null) {
                selected=new Selection(ItemIcons.Kind.ITEM,choice.id,null,null); itemChoice.setSelected(true);
                itemChoice.setText(choice.name); itemChoice.setIcon(new Thumbnail(choice.image)); summary.setIcon(null); summary.setText("Selected: "+choice.name);
                if(choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
                    ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) itemChoice.repaint(); }));
            }
        });
        itemChoice.addActionListener(e -> { ItemSearch.Choice choice=itemPicker.selected(); if(choice!=null) { selected=new Selection(ItemIcons.Kind.ITEM,choice.id,null,null); summary.setText("Selected: "+choice.name); } });
        tabs.addTab("Item pictures",picture);
        add(tabs,BorderLayout.CENTER);
        JPanel footer=new JPanel(new BorderLayout(4,4)); footer.add(summary,BorderLayout.NORTH);
        JButton upload=new JButton("Add image file…"); footer.add(upload,BorderLayout.SOUTH);
        upload.addActionListener(e -> {
            java.util.List<net.runelite.client.util.Filepath> files=new net.runelite.client.util.Filepath.Chooser().setIsOpen().setAcceptsFiles().addExtensionFilter("Images","png","jpg","jpeg","gif").showDialog(this);
            if(files.isEmpty()) return;
            upload.setEnabled(false);
            new SwingWorker<String,Void>() {
                protected String doInBackground() throws Exception { return IconImages.read(files.get(0)); }
                protected void done() {
                    if(closed) return;
                    upload.setEnabled(true);
                    try {
                        String encoded=get();
                        selected=new Selection(ItemIcons.Kind.IMAGE,0,"improved-icons/upload-"+Integer.toHexString(encoded.hashCode())+".png",encoded);
                        group.clearSelection(); summary.setText("Selected: uploaded image"); summary.setIcon(new Thumbnail(IconImages.decode(encoded)));
                    } catch(Exception ex) { summary.setText("Image not loaded: "+(ex.getCause()==null?ex.getMessage():ex.getCause().getMessage())); }
                }
            }.execute();
        });
        add(footer,BorderLayout.SOUTH);
    }
    private JToggleButton tile(JPanel panel,String name,BufferedImage image,Selection selection)
    {
        String label=name.length()>15?name.substring(0,12)+"…":name;
        JToggleButton button=new JToggleButton(label,new Thumbnail(image)); button.setToolTipText(name);
        button.setHorizontalTextPosition(SwingConstants.CENTER); button.setVerticalTextPosition(SwingConstants.BOTTOM);
        button.setPreferredSize(new Dimension(100,64)); button.setMargin(new Insets(4,3,4,3));
        group.add(button); panel.add(button);
        button.addActionListener(e -> { selected=selection; summary.setIcon(null); summary.setText("Selected: "+name); }); return button;
    }
    void currentItem(ItemSearch.Choice choice) {
        current.setIcon(new Thumbnail(choice==null?null:choice.image)); current.setToolTipText(choice==null?"The matching item's own picture":choice.name);
        if(choice!=null && choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
            ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) current.repaint(); }));
    }
    Selection selection() { return selected; }
    void close() { closed=true; itemPicker.close(); }
    static final class Thumbnail implements Icon
    {
        private final BufferedImage image;
        Thumbnail(BufferedImage image) { this.image=image; }
        public int getIconWidth() { return 32; }
        public int getIconHeight() { return 32; }
        public void paintIcon(Component c,Graphics g,int x,int y) {
            if(image==null) { g.setColor(Color.GRAY); g.drawRect(x+7,y+7,18,18); g.drawString("?",x+12,y+21); return; }
            double scale=Math.min(32d/image.getWidth(),32d/image.getHeight());
            int width=(int)(image.getWidth()*scale),height=(int)(image.getHeight()*scale);
            g.drawImage(image,x+(32-width)/2,y+(32-height)/2,width,height,c);
        }
    }
    private static BufferedImage hiddenImage()
    {
        BufferedImage image=new BufferedImage(32,32,BufferedImage.TYPE_INT_ARGB); Graphics2D g=image.createGraphics();
        try { g.setColor(new Color(220,85,85)); g.setStroke(new BasicStroke(3)); g.drawOval(4,4,23,23); g.drawLine(7,25,25,7); } finally { g.dispose(); } return image;
    }
}

