        button(buttons,"Import Loot Filters",this::importLoot);
        button(buttons,"Import/export icons",this::exchange);
        button(buttons,"Filter setup / backup",this::filterBackup);
        button(buttons,"Import filter sounds",this::importSounds);
        button(buttons,"Undo filter import",() -> { icons.filters.undo(); refresh(); JOptionPane.showMessageDialog(panel,icons.filters.status()); });
        button(buttons,"Undo / redo",() -> { icons.undo(); refresh(); });
        panel.add(buttons,BorderLayout.SOUTH);
        dialog=new JDialog(SwingUtilities.getWindowAncestor(owner),"Item icons",Dialog.ModalityType.MODELESS);
        dialog.addWindowListener(new java.awt.event.WindowAdapter() { @Override public void windowClosed(java.awt.event.WindowEvent e) { closed=true; } });
        dialog.setContentPane(panel); dialog.setSize(620,480); dialog.setMinimumSize(new Dimension(480,320));
        dialog.setLocationRelativeTo(owner); dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE); refresh(); dialog.setVisible(true);
    }
    private void refresh() { if(icons.filters!=null) filterStatus.setText(icons.filters.status()); model.clear(); for(ItemIcons.Assignment a:icons.snapshot()) { model.addElement(a); } }
    private void button(JPanel parent,String label,Runnable action)
    {
        JButton b=new JButton(label); b.addActionListener(e -> { try { action.run(); } catch(IllegalArgumentException ex) { JOptionPane.showMessageDialog(panel,ex.getMessage(),"Item icons",JOptionPane.WARNING_MESSAGE); } }); parent.add(b);
    }
    private Object profile() { return icons.configs.getProfile(); }
    private void checkProfile(Object original) { if(closed) throw new IllegalArgumentException("Icon editor was closed."); if(!Objects.equals(original,profile())) { refresh(); throw new IllegalArgumentException("RuneLite profile changed. Reopen this action."); } }
    private void assign()
    {
        Object original=profile();
        ItemPicker picker=new ItemPicker(icons.search);
        FilterIcons.Prepared filter=icons.filters.snapshot();
        IconPalette palette=new IconPalette(icons,filter==null?Collections.emptyMap():filter.bundle.images,false);
        picker.onSelect(palette::currentItem);
        JPanel form=new JPanel(new GridLayout(1,2,10,0)); form.add(picker); form.add(palette); form.setPreferredSize(new Dimension(680,300));
        ItemIcons.Assignment assignment=new ItemIcons.Assignment();
        try {
            if(JOptionPane.showConfirmDialog(panel,form,"Find item and choose icon",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return;
            checkProfile(original);
            IconPalette.Selection selected=palette.selection();
            assignment.name=picker.value().trim(); assignment.kind=selected.kind;
            assignment.iconId=selected.item; assignment.image=selected.image;
            if(assignment.name.contains("*")) throw new IllegalArgumentException("Manual overrides use exact item names. Use Edit filter rules for wildcards.");
            List<ItemIcons.Assignment> next=icons.snapshot(); next.removeIf(old -> old.key().equals(assignment.key())); next.add(assignment); icons.save(next); refresh();
        } finally { picker.close(); palette.close(); }
    }
    private <T> void background(java.util.concurrent.Callable<T> work,java.util.function.Consumer<T> done)
    {
        new SwingWorker<T,Void>() {
            protected T doInBackground() throws Exception { return work.call(); }
            protected void done() {
                if(closed) return;
                try { done.accept(get()); }
                catch(Exception e) { Throwable cause=e.getCause()==null ? e : e.getCause(); JOptionPane.showMessageDialog(panel,cause.getMessage(),"Import not applied",JOptionPane.WARNING_MESSAGE); }
            }
        }.execute();
    }
    private static String readFilter(Filepath file) throws IOException
    {
        try(java.io.InputStream in=file.openInputStream()) {
            byte[] data=in.readNBytes(1000001); if(data.length>1000000) throw new IllegalArgumentException("Filter exceeds 1 MB.");
            return new String(data,java.nio.charset.StandardCharsets.UTF_8);
        }
    }
    void importLoot()
    {
        Object original=profile();
        Object[] choices={"Choose .rs2f file","Paste Filterscape text","Cancel"};
        int choice=JOptionPane.showOptionDialog(panel,"Import icon rules from a Filterscape export or Loot Filters script.\nThe original files and settings remain untouched.","Import Loot Filters",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,choices,choices[0]);
        if(choice==0) {
            List<Filepath> files=new Filepath.Chooser().setIsOpen().setAcceptsFiles().addExtensionFilter("Loot Filters","rs2f","txt").showDialog(panel);
            if(files.isEmpty()) return;
            background(() -> readFilter(files.get(0)),source -> compileImport(source,original));
        } else if(choice==1) {
            JTextArea text=new JTextArea(18,48);
            if(JOptionPane.showConfirmDialog(panel,new JScrollPane(text),"Paste generated filter",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION) compileImport(text.getText(),original);
        }
    }
    private void compileImport(String source,Object original)
    {
        checkProfile(original);
        background(() -> com.improvedlooting.rs2f.LootFilter.compile(source),program -> {
            checkProfile(original);
            FilterIcons.Bundle bundle=new FilterIcons.Bundle(); bundle.compressedSource=FilterIcons.compress(source);
            Set<String> files=program.files();
            if(files.size()>128) throw new IllegalArgumentException("Use at most 128 custom images.");
            for(String file:files) IconImages.safeName(file);
            if(files.isEmpty()) { background(() -> icons.filters.prepare(bundle),ready -> previewFilter(ready,original)); return; }
            JOptionPane.showMessageDialog(panel,"This filter references "+files.size()+" images. Select the Loot Filters icons folder (usually .runelite/loot-filters/icons).\nImages will be embedded in our backup; originals stay untouched.\nAll referenced images must be present before import can apply.");
            List<Filepath> folders=new Filepath.Chooser().setIsOpen().setAcceptsDirectories().showDialog(panel);
            if(folders.isEmpty()) return;
            background(() -> {
                for(String file:files) {
                    Filepath path=folders.get(0);
                    for(String segment:IconImages.safeName(file).split("/")) path=path.joinSegment(segment);
                    bundle.images.put(file,IconImages.read(path));
                }
                return icons.filters.prepare(bundle);
            },ready -> previewFilter(ready,original));
        });
    }
    private void previewFilter(FilterIcons.Prepared ready,Object original)
    {
        checkProfile(original);
        String message=ready.program.rules.size()+" rules and "+ready.images.size()+" images ready.\n\nConditions, macros, rule order and inherited icons are preserved.\nLabels, colors, hiding, sounds and loot beams follow the same rules. Master controls remain in the side panel.\nManual item assignments take priority. This replaces the previously imported filter; Undo filter import restores it.";
        if(JOptionPane.showConfirmDialog(panel,message,"Review filter import",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return;
        checkProfile(original); icons.filters.save(ready); refresh(); JOptionPane.showMessageDialog(panel,"Imported. Ground display follows the Appearance tab.");
    }
    private void filterBackup()
    {
        Object original=profile();
        Object[] options={"Copy / paste backup","Disable imported filter","Cancel"};
        int action=JOptionPane.showOptionDialog(panel,icons.filters.status(),"Imported filter",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,options,options[0]);
        if(action==1) { checkProfile(original); icons.filters.save(null); refresh(); return; }
        if(action!=0) return;
        JTextArea text=new JTextArea(icons.filters.export(),18,48); text.setLineWrap(true);
        if(JOptionPane.showConfirmDialog(panel,new JScrollPane(text),"Copy to export; paste a filter setup to import",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return;
        String raw=text.getText(); background(() -> icons.filters.parse(raw),ready -> previewFilter(ready,original));
    }
    private void importSounds()
    {
        Object original=profile(); String before=icons.filters.export();
        if(before.isBlank()) throw new IllegalArgumentException("Import or save a filter first.");
        FilterIcons.Bundle bundle=icons.gson.fromJson(before,FilterIcons.Bundle.class);
        Set<String> names=new LinkedHashSet<>();
        for(com.improvedlooting.rs2f.FilterRule rule:com.improvedlooting.rs2f.LootFilter.compile(FilterIcons.source(bundle)).rules) {
            com.improvedlooting.rs2f.model.SoundProvider sound=rule.getDisplay().getSound();
            if(sound!=null && sound.getFile()!=null) { IconImages.safeName(sound.getFile()); names.add(sound.getFile()); }
        }
        if(names.isEmpty()) { JOptionPane.showMessageDialog(panel,"This filter has no custom sound files."); return; }
        JOptionPane.showMessageDialog(panel,"Select the folder containing the filter's sound files. Copies are saved with your filter; the originals are unchanged.");
        List<Filepath> folders=new Filepath.Chooser().setIsOpen().setAcceptsDirectories().showDialog(panel);
        if(folders.isEmpty()) return;
        background(() -> {
            if(bundle.sounds==null) bundle.sounds=new LinkedHashMap<>();
            for(String name:names) {
                Filepath file=folders.get(0);
                for(String part:IconImages.safeName(name).split("/")) file=file.joinSegment(part);
                bundle.sounds.put(name,FilterSounds.read(file));
            }
            return icons.filters.prepare(bundle);
        },ready -> {
            checkProfile(original);
            if(!Objects.equals(before,icons.filters.export())) throw new IllegalArgumentException("The active filter changed. Import sounds again.");
            icons.filters.save(ready); refresh(); JOptionPane.showMessageDialog(panel,"Imported "+ready.sounds.size()+" sound files. Enable Drop sounds to use them.");
        });
    }
    private void preview(List<ItemIcons.Assignment> imported,Object original)
    {
        JTextArea text=new JTextArea(14,42); text.setEditable(false);
        text.append("ICON ASSIGNMENTS ONLY. Filter colors, sounds and hiding rules are not imported.\n\n");
        for(ItemIcons.Assignment a:imported) { text.append(a.toString()+"\n"); }
        Object[] actions={"Merge (keep existing)","Replace all","Cancel"};
        int choice=JOptionPane.showOptionDialog(panel,new JScrollPane(text),"Review icon import",JOptionPane.DEFAULT_OPTION,JOptionPane.PLAIN_MESSAGE,null,actions,actions[0]);
        if(choice!=0 && choice!=1) { return; }
        checkProfile(original);
        LinkedHashMap<String,ItemIcons.Assignment> next=new LinkedHashMap<>();
        if(choice==0) { for(ItemIcons.Assignment a:icons.snapshot()) { next.put(a.key(),a); } }
        for(ItemIcons.Assignment a:imported) { next.putIfAbsent(a.key(),a); }
        icons.save(new ArrayList<>(next.values())); refresh();
    }
    private void exchange()
    {
        Object original=profile(); JTextArea json=new JTextArea(icons.export(),16,42); json.setLineWrap(true);
        if(JOptionPane.showConfirmDialog(panel,new JScrollPane(json),"Copy to export; paste to import",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) { return; }
        checkProfile(original); preview(icons.parse(json.getText()),original);
    }
}

package com.improvedlooting;

import com.google.gson.Gson;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;

/** Our own assignments; never writes Loot Filters configuration or files. */
@Singleton
class ItemIcons
{
    static final String KEY="itemIconAssignments", BACKUP="itemIconBackup";
    enum Kind { HEART, STAR, DIAMOND, CURRENT_ITEM, ITEM, SPRITE, IMAGE }
    static final class Assignment
    {
        String image; String name; int itemId=-1; Kind kind; int iconId; int spriteIndex;
        String key() { return itemId>=0 ? "id:"+itemId : "name:"+name.toLowerCase(Locale.ROOT); }
        @Override public String toString() { return (itemId>=0 ? "Item #"+itemId : name)+" — "+kind+(kind==Kind.ITEM || kind==Kind.SPRITE ? " #"+iconId : ""); }
    }
    @Inject ConfigManager configs;
    @Inject Gson gson;
    @Inject ItemManager items;
    @Inject SpriteManager sprites;
    @Inject FilterIcons filters;
    @Inject ItemSearch search;
    @Inject PriceTiers tiers;
    @Inject net.runelite.client.audio.AudioPlayer audio;
    private final Map<String,BufferedImage> imageCache=new LinkedHashMap<>();
    private final Map<Kind,BufferedImage> builtins=new EnumMap<>(Kind.class);
    private long cachedPixels;
    private String cached;
    private List<Assignment> assignments=Collections.emptyList();
    synchronized List<Assignment> snapshot()
    {
        String raw=configs.getConfiguration(ImprovedLootingConfig.GROUP,KEY);
        if(!Objects.equals(raw,cached))
        {
            try { assignments=parse(raw==null ? "[]" : raw); }
            catch(IllegalArgumentException e) { assignments=Collections.emptyList(); }
            cached=raw; imageCache.clear();cachedPixels=0;
        }
        return new ArrayList<>(assignments);
    }
    List<Assignment> parse(String raw)
    {
        if(raw==null || raw.length()>6000000) { throw new IllegalArgumentException("Icon data is too large."); }
        try
        {
            Assignment[] data=gson.fromJson(raw,Assignment[].class);
            if(data==null || data.length>500) { throw new IllegalArgumentException("Use at most 500 assignments."); }
            LinkedHashMap<String,Assignment> unique=new LinkedHashMap<>();
            long pixels=0;
            for(Assignment a:data)
            {
                if(a==null || a.kind==null || a.itemId < -1 || a.itemId>100000 || a.iconId<0 || a.iconId>100000 || a.spriteIndex<0 || a.spriteIndex>255
                    || (a.itemId<0 && (a.name==null || a.name.trim().isEmpty() || a.name.length()>120 || a.name.contains("<") || a.name.contains(">"))))
                { throw new IllegalArgumentException("Invalid icon assignment."); }
                if(a.kind==Kind.IMAGE) { BufferedImage image=IconImages.decode(a.image);pixels+=(long)image.getWidth()*image.getHeight();if(pixels>16000000)throw new IllegalArgumentException("Assignment images exceed 16 million pixels"); }
                if(a.name!=null) { a.name=a.name.trim(); }
                unique.put(a.key(),a);
            }
            return new ArrayList<>(unique.values());
        }
        catch(com.google.gson.JsonParseException e) { throw new IllegalArgumentException("Invalid icon JSON."); }
    }
    String export() { return gson.toJson(snapshot()); }
    void save(List<Assignment> next)
    {
        String json=gson.toJson(next); parse(json);
        configs.setConfiguration(ImprovedLootingConfig.GROUP,BACKUP,export());
        configs.setConfiguration(ImprovedLootingConfig.GROUP,KEY,json);
    }
    void undo()
    {
        String before=configs.getConfiguration(ImprovedLootingConfig.GROUP,BACKUP);
        if(before!=null) { save(parse(before)); }
    }
    Assignment find(int id)
    {
        List<Assignment> entries=snapshot();
        for(Assignment a:entries) { if(a.itemId==id) { return a; } }
        if(entries.isEmpty()) { return null; }
        String name=items.getItemComposition(id).getName();
        for(Assignment a:entries) { if(a.itemId<0 && a.name.equalsIgnoreCase(name)) { return a; } }
        return null;
    }
    synchronized BufferedImage image(Assignment a,int id)
    {
        if(a==null) { return null; }
        if(a.kind==Kind.CURRENT_ITEM || a.kind==Kind.ITEM) { return items.getImage(a.kind==Kind.CURRENT_ITEM ? id : a.iconId); }
        if(a.kind==Kind.IMAGE) {
            BufferedImage cached=imageCache.get(a.image);if(cached!=null)return cached;
            BufferedImage next=IconImages.decode(a.image);long pixels=(long)next.getWidth()*next.getHeight();
            if(imageCache.size()>=128 || cachedPixels+pixels>16000000){imageCache.clear();cachedPixels=0;}
            imageCache.put(a.image,next);cachedPixels+=pixels;return next;
        }
        if(a.kind==Kind.SPRITE) { try { return sprites.getSprite(a.iconId,a.spriteIndex); } catch(IndexOutOfBoundsException e) { return null; } }
        if(builtins.containsKey(a.kind)) { return builtins.get(a.kind); }
        BufferedImage result=new BufferedImage(17,15,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=result.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
            if(a.kind==Kind.HEART) { g.setColor(new Color(255,105,110)); g.fillOval(1,1,8,8); g.fillOval(8,1,8,8); g.fillPolygon(new int[]{1,16,8},new int[]{6,6,14},3); }
            else if(a.kind==Kind.DIAMOND) { g.setColor(Color.CYAN); g.fillPolygon(new int[]{8,15,8,1},new int[]{0,7,14,7},4); }
            else { g.setColor(new Color(255,210,60)); Polygon star=new Polygon(); for(int i=0;i<10;i++) { double angle=-Math.PI/2+i*Math.PI/5; double radius=i%2==0 ? 7 : 3; star.addPoint(8+(int)(Math.cos(angle)*radius),7+(int)(Math.sin(angle)*radius)); } g.fillPolygon(star); }
        }
        finally { g.dispose(); }
        builtins.put(a.kind,result);
        return result;
    }
}

package com.improvedlooting;

import java.awt.*;
import java.awt.event.*;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.event.*;

/** Search suggestions stay inside the editor; no floating menus or focus stealing. */
final class ItemPicker extends JPanel
{
    private final JTextField query=new JTextField();
    private final DefaultListModel<ItemSearch.Choice> model=new DefaultListModel<>();
    private final JList<ItemSearch.Choice> results=new JList<>(model);
    private final JLabel hint=new JLabel("Type at least 2 letters to search items");
    private final javax.swing.Timer debounce;
    private volatile int revision;
    private volatile boolean closed;
    private boolean choosing;
    private ItemSearch.Choice selected;
    private Consumer<ItemSearch.Choice> onSelect=c -> {};
    ItemPicker(ItemSearch search) { this(search,4); }
    ItemPicker(ItemSearch search,int rows)
    {
        super(new BorderLayout(4,4)); add(query,BorderLayout.NORTH);
        results.setVisibleRowCount(rows); results.setFixedCellHeight(34); results.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        results.setCellRenderer(new DefaultListCellRenderer() {
            @Override public Component getListCellRendererComponent(JList<?> list,Object value,int index,boolean selected,boolean focus) {
                JLabel label=(JLabel)super.getListCellRendererComponent(list,value,index,selected,focus);
                ItemSearch.Choice choice=(ItemSearch.Choice)value; label.setText(choice.name); label.setIcon(choice.image==null?null:new ImageIcon(choice.image));
                label.setBorder(BorderFactory.createEmptyBorder(2,6,2,6)); return label;
            }
        });
        JScrollPane scroll=new JScrollPane(results); scroll.setPreferredSize(new Dimension(240,rows*34+4)); add(scroll,BorderLayout.CENTER); add(hint,BorderLayout.SOUTH);
        debounce=new javax.swing.Timer(180,e -> {
            int current=revision; String term=query.getText();
            if(term.trim().length()<2) { hint.setText("Type at least 2 letters to search items"); return; }
            hint.setText("Searching item catalogue…");
            search.search(term,() -> !closed && revision==current,choices -> {
                if(closed || revision!=current) return;
                model.clear(); for(ItemSearch.Choice choice:choices) {
                    model.addElement(choice);
                    if(choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
                        ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) results.repaint(); }));
                }
                hint.setText(choices.isEmpty()?"No matches. Exact names / * still work.":"Click a match, or use ↓ and Enter.");
                results.repaint();
            });
        }); debounce.setRepeats(false);
        query.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { changed(); }
            public void removeUpdate(DocumentEvent e) { changed(); }
            public void changedUpdate(DocumentEvent e) { changed(); }
            private void changed() { if(choosing) return; selected=null; revision++; model.clear(); debounce.restart(); onSelect.accept(null); }
        });
        query.addKeyListener(new KeyAdapter() { @Override public void keyPressed(KeyEvent e) { if(e.getKeyCode()==KeyEvent.VK_DOWN && !model.isEmpty()) { results.setSelectedIndex(0); results.requestFocusInWindow(); e.consume(); } } });
        results.addMouseListener(new MouseAdapter() { @Override public void mouseClicked(MouseEvent e) { int i=results.locationToIndex(e.getPoint()); if(i>=0 && results.getCellBounds(i,i).contains(e.getPoint())) choose(); } });
        results.getInputMap().put(KeyStroke.getKeyStroke("ENTER"),"choose");
        results.getActionMap().put("choose",new AbstractAction() { public void actionPerformed(ActionEvent e) { choose(); } });
    }
    void onSelect(Consumer<ItemSearch.Choice> action) { onSelect=action; }
    private void choose()
    {
        ItemSearch.Choice choice=results.getSelectedValue(); if(choice==null) return;
        choosing=true; query.setText(choice.name); choosing=false; selected=choice; revision++; debounce.stop();
        hint.setText("Selected: "+choice.name); onSelect.accept(choice); query.requestFocusInWindow();
    }
    void value(String name) { query.setText(name); }
    String value() { return query.getText(); }
    ItemSearch.Choice selected() { return selected; }
    void close() { closed=true; revision++; debounce.stop(); }
}

package com.improvedlooting;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/** Read-only, incremental catalogue. Includes untradeables; never scans on the EDT. */
@Singleton
final class ItemSearch
{
    static final class Choice
    {
        final int id;
        final String name, lower;
        BufferedImage image;
        Choice(int id, String name) { this.id=id; this.name=name; this.lower=name.toLowerCase(Locale.ROOT); }
        @Override public String toString() { return name; }
    }
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject ItemManager items;
    private final Map<String, Choice> catalogue=new LinkedHashMap<>();
    private int cursor, size;

    void search(String query, BooleanSupplier wanted, Consumer<java.util.List<Choice>> done)
    {
        thread.invokeLater(() -> {
            if(!wanted.getAsBoolean()) return true;
            int count=Math.min(client.getItemCount(),100000);
            if(count<=0) { SwingUtilities.invokeLater(() -> done.accept(Collections.emptyList())); return true; }
            if(count!=size) { catalogue.clear(); cursor=0; size=count; }
            int end=Math.min(cursor+512,size);
            while(cursor<end) {
                int id=cursor++; ItemComposition item=items.getItemComposition(id);
                String name=item.getName();
                if(name!=null && !name.isBlank() && !name.equalsIgnoreCase("null") && item.getNote()==-1 && item.getPlaceholderTemplateId()==-1)
                    catalogue.putIfAbsent(name.toLowerCase(Locale.ROOT),new Choice(id,name));
            }
            if(cursor<size) return false;
            java.util.List<Choice> result=rank(catalogue.values(),query);
            for(Choice choice:result) choice.image=items.getImage(choice.id);
            SwingUtilities.invokeLater(() -> { if(wanted.getAsBoolean()) done.accept(result); });
            return true;
        });
    }
    static java.util.List<Choice> rank(Collection<Choice> choices,String query)
    {
        String q=query.trim().toLowerCase(Locale.ROOT);
        if(q.length()<2) return Collections.emptyList();
        java.util.List<Choice> result=new ArrayList<>();
        for(Choice choice:choices) if(choice.lower.contains(q)) result.add(choice);
        result.sort(Comparator.comparingInt((Choice c) -> c.lower.equals(q)?0:c.lower.startsWith(q)?1:2).thenComparing(c -> c.lower));
        return new ArrayList<>(result.subList(0,Math.min(40,result.size())));
    }
}

package com.improvedlooting;

import java.util.*;
import javax.inject.*;
import net.runelite.client.config.ConfigManager;

/** Copy only loot data; never change or remove another plugin's settings. */
@Singleton
final class LegacyImport
{
    @Inject ConfigManager configs;
    @Inject FilterIcons filters;
    @Inject ItemIcons icons;
    static final String SOURCE="improvedmenus";
    Map<String,String> prepare()
    {
        Map<String,String> copy=new LinkedHashMap<>();
        String filter=configs.getConfiguration(SOURCE,FilterIcons.KEY);
        String assignments=configs.getConfiguration(SOURCE,ItemIcons.KEY);
        if(filter!=null && !filter.isBlank()) { filters.parse(filter); copy.put(FilterIcons.KEY,filter); }
        if(assignments!=null && !assignments.isBlank()) { icons.parse(assignments); copy.put(ItemIcons.KEY,assignments); }
        return copy;
    }
    void apply(Map<String,String> copy)
    {
        // Check every destination before writing any data. An existing setup is never overwritten.
        for(String key:copy.keySet()) {
            String existing=configs.getConfiguration(ImprovedLootingConfig.GROUP,key);
            if(existing!=null && !existing.isBlank()) throw new IllegalArgumentException("A setup already exists here. Export it and clear it before copying another setup.");
        }
        copy.forEach((key,value)->configs.setConfiguration(ImprovedLootingConfig.GROUP,key,value));
        filters.reload();
    }
}

