import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;

/** Client-thread alert decisions, bounded history; imported audio plays off the client thread. */
@Singleton
final class LootAlerts
{
    @Inject Client client;
    @Inject ImprovedLootingConfig config;
    @Inject Notifier notifier;
    @Inject AudioPlayer audio;
    @Inject ScheduledExecutorService executor;
    @Inject PriceTiers tiers;
    private final AtomicBoolean playing = new AtomicBoolean();
    private final Map<String, Integer> recent = new LinkedHashMap<>();
    private final Deque<Card> cards = new ArrayDeque<>();
    private int lastSound = Integer.MIN_VALUE / 2;
    private int notificationTick=-1, notifications;
    private volatile int generation;
    static final class Card
    {
        final String text; final int expires;
        Card(String text, int expires) { this.text = text; this.expires = expires; }
    }
    void clear() { generation++; recent.clear(); cards.clear(); lastSound = Integer.MIN_VALUE / 2; }
    void tick()
    {
        int tick = client.getTickCount();
        recent.values().removeIf(expiry -> expiry < tick);
        cards.removeIf(card -> card.expires < tick);
    }
    List<Card> cards() { return new ArrayList<>(cards); }
    void drop(GroundLoot.Entry entry, FilterIcons.Prepared filter)
    {
        if (entry.display == null || entry.display.isHidden() || LootDisplayOptions.ownershipHidden(config,entry)) return;
        int tick = client.getTickCount();
        String key = entry.item.getId() + ":" + entry.tile.getLocalLocation() + ":" + entry.facts.getQuantity();
        if (recent.containsKey(key)) return;
        if (recent.size() >= 256) recent.remove(recent.keySet().iterator().next());
        recent.put(key, tick + 3);
        String message = "Loot: " + entry.facts.getName() + " × " + entry.facts.getQuantity();
        if (entry.display.isNotify())
        {
            if (config.lootNotifications()) notifyBounded(message);
            card(message);
        }
        SoundProvider sound = entry.display.getSound();
        byte[] custom = null;
        PriceTiers.Ready ready = config.priceTiersEnabled() ? tiers.snapshot() : null;
        if (ready != null)
        {
            int index = PriceTiers.index(ready.setup, PriceTiers.value(entry.facts.getGePrice(), entry.facts.getQuantity()));
            PriceTiers.Sound mode = ready.setup.tiers[index].sound;
            if (mode != PriceTiers.Sound.RULE) sound = null;
            if (mode == PriceTiers.Sound.CUSTOM) custom = ready.audio[index];
        }
        if (custom == null && sound != null && sound.getFile() != null) custom = filter.sounds.get(sound.getFile());
        if (!config.lootSounds() || clamp(config.alertVolume(), 0, 100) == 0
            || tick - lastSound < Math.ceil(clamp(config.soundCooldown(), 0, 60) / 0.6)) return;
        if (custom != null)
        {
            if (!playing.compareAndSet(false, true)) return;
            byte[] bytes = custom; int token = generation; float gain = gain(config.alertVolume());
            lastSound = tick;
            executor.execute(() -> {
                try { if (token == generation && config.lootSounds()) audio.play(new ByteArrayInputStream(bytes), gain); }
                catch (Exception ignored) { }
                finally { playing.set(false); }
            });
        }
        else if (sound != null && sound.getEffect() != null)
        {
            client.playSoundEffect(sound.getEffect(), clamp(config.alertVolume(), 0, 100) * 127 / 100);
            lastSound = tick;
        }
    }
    void despawn(GroundLoot.Entry entry, int seconds)
    {
        if (LootDisplayOptions.ownershipHidden(config,entry)) return;
        int threshold = clamp(config.despawnSeconds(), 1, 120);
        if (seconds > threshold) entry.warningArmed = true;
        if (!entry.warningArmed || entry.warned || seconds < 0 || seconds > threshold) return;
        entry.warned = true;
        if (!config.despawnWarnings() || entry.display.isHidden()
            || PriceTiers.value(entry.facts.getGePrice(), entry.facts.getQuantity()) < Math.max(0, config.despawnMinimum())) return;
        String message = entry.facts.getName() + " despawns in " + seconds + "s";
        notifyBounded(message); card(message);
    }
    private void notifyBounded(String message)
    {
        int tick=client.getTickCount();if(notificationTick!=tick){notificationTick=tick;notifications=0;}
        if(notifications++<3)notifier.notify(message);
    }
    private void card(String message)
    {
        if (!config.notificationCards()) return;
        while (cards.size() >= 5) cards.removeFirst();
        cards.addLast(new Card(message, client.getTickCount() + 13));
    }
    static float gain(int percent) { return percent <= 0 ? -80f : (float)(20 * Math.log10(clamp(percent, 1, 100) / 100.0)); }
    static int clamp(int value, int min, int max) { return Math.max(min, Math.min(max, value)); }
}

package com.improvedlooting;

import java.awt.*;
import java.awt.event.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.swing.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.LinkBrowser;

/** Read-only nearby view. Selecting a row highlights its tile; it never sends game actions. */
final class LootBrowser
{
    private final GroundLoot loot;
    private final ItemIcons icons;
    private final ClientThread clientThread;
    private final LootPreferences preferences;
    private final DefaultListModel<LootRow> model=new DefaultListModel<>();
    private final JList<LootRow> list=new JList<>(model);
    private final JTextField search=new JTextField(),categoryFilter=new JTextField(),category=new JTextField();
    private final JTextArea inspector=new JTextArea();
    private final JCheckBox hidden=new JCheckBox("Include hidden",true),grid=new JCheckBox("Grid");
    private final JComboBox<String> order=new JComboBox<>(new String[]{"Value","Distance","Time remaining","Name"});
    private final JLabel status=new JLabel();
    private final javax.swing.Timer timer;
    private final Object profile;
    private JDialog dialog;
    private FilterEditor editor;
    private volatile boolean closed;
    private boolean refreshing;
    private int selectionRevision;
    LootBrowser(GroundLoot loot,ItemIcons icons,ClientThread thread,LootPreferences preferences)
    { this.loot=loot;this.icons=icons;this.clientThread=thread;this.preferences=preferences;profile=icons.configs.getProfile(); timer=new javax.swing.Timer(600,e->refresh()); }
    JPanel content()
    {
        JPanel root=new JPanel(new BorderLayout(8,8));root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
        JPanel filters=new JPanel(new GridLayout(2,3,8,5));
        search.setToolTipText("Filter nearby item names");categoryFilter.setToolTipText("Filter your categories");
        filters.add(new JLabel("Search items"));filters.add(new JLabel("Category contains"));filters.add(order);
        filters.add(search);filters.add(categoryFilter);
        JPanel mode=new JPanel(new FlowLayout(FlowLayout.LEFT,3,0));mode.add(hidden);mode.add(grid);filters.add(mode);root.add(filters,BorderLayout.NORTH);
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);list.setFixedCellHeight(60);
        list.setCellRenderer(new DefaultListCellRenderer(){
            public Component getListCellRendererComponent(JList<?> l,Object value,int index,boolean selected,boolean focus){
                JLabel label=(JLabel)super.getListCellRendererComponent(l,value,index,selected,focus);LootRow r=(LootRow)value;
                label.setText((grid.isSelected()?"<html><body style='width:185px'>":"<html>")+escape(r.name)+" × "+r.quantity+(r.hidden?" · hidden":"")+"<br>"+String.format("%,d",r.value)+" gp · "+r.distance+" tiles · "+(r.seconds<0?"time unknown":r.seconds+"s")+(r.category.isEmpty()?"":" · "+escape(r.category))+"</html>");
                label.setIcon(r.image==null?null:new IconPalette.Thumbnail(r.image));
                label.setBorder(BorderFactory.createEmptyBorder(4,6,4,6));return label;
            }});
        list.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&!refreshing) inspect();});
        grid.addActionListener(e->{list.setLayoutOrientation(grid.isSelected()?JList.HORIZONTAL_WRAP:JList.VERTICAL);list.setVisibleRowCount(grid.isSelected()?-1:0);list.setFixedCellWidth(grid.isSelected()?220:-1);list.setFixedCellHeight(grid.isSelected()?96:60);});
        inspector.setEditable(false);inspector.setLineWrap(true);inspector.setWrapStyleWord(true);inspector.setText("Select an item to see the rules and final settings. Selection highlights its tile for 10 seconds.");
        JPanel detail=new JPanel(new BorderLayout(6,6));detail.add(new JScrollPane(inspector),BorderLayout.CENTER);
        JPanel actions=new JPanel(new GridLayout(0,2,6,6));
        for(LootPreferences.Action action:LootPreferences.Action.values()) button(actions,action==LootPreferences.Action.FILTER?"Use filter":title(action.name()),()->override(action));
        actions.add(new JLabel("Item category"));actions.add(category);
        button(actions,"Save category",()->override(null));button(actions,"Create filter rule",this::createRule);
        button(actions,"Wiki drop table",this::wiki);button(actions,"Source availability",this::source);
        detail.add(actions,BorderLayout.SOUTH);
        JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(list),detail);split.setResizeWeight(.55);split.setDividerLocation(470);root.add(split,BorderLayout.CENTER);
        root.add(status,BorderLayout.SOUTH);refresh();return root;
    }
    void open(Component owner){dialog=new JDialog(SwingUtilities.getWindowAncestor(owner),"Nearby loot — Improved Looting",Dialog.ModalityType.MODELESS);dialog.setContentPane(content());dialog.setSize(960,650);dialog.setMinimumSize(new Dimension(750,500));dialog.setLocationRelativeTo(owner);dialog.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){close();}});dialog.setVisible(true);timer.start();}
    private boolean valid(){return !closed&&Objects.equals(profile,icons.configs.getProfile());}
    private void refresh()
    {
        if(!valid()){close();return;}
        LootRow before=list.getSelectedValue();long key=before==null?-1:before.key;
        java.util.List<LootRow> rows=new ArrayList<>();String query=search.getText().trim().toLowerCase(Locale.ROOT),cat=categoryFilter.getText().trim().toLowerCase(Locale.ROOT);
        for(LootRow row:loot.rows())if((hidden.isSelected()||!row.hidden)&&row.name.toLowerCase(Locale.ROOT).contains(query)&&row.category.toLowerCase(Locale.ROOT).contains(cat))rows.add(row);
        Comparator<LootRow> sort=order.getSelectedIndex()==1?Comparator.comparingInt(r->r.distance):order.getSelectedIndex()==2?Comparator.comparingInt(r->r.seconds<0?Integer.MAX_VALUE:r.seconds):order.getSelectedIndex()==3?Comparator.comparing(r->r.name,String.CASE_INSENSITIVE_ORDER):Comparator.<LootRow>comparingLong(r->r.value).reversed();rows.sort(sort.thenComparingLong(r->r.key));
        refreshing=true;model.clear();for(LootRow row:rows){model.addElement(row);if(row.key==key)list.setSelectedIndex(model.size()-1);}refreshing=false;
        if(before!=null&&list.getSelectedValue()==null){selectionRevision++;inspector.setText("That pile is no longer in this view.");}
        status.setText(loot.status()+" · "+rows.size()+" shown (browser limit 512) · selection never picks up items");
    }
    private void inspect()
    {
        LootRow row=list.getSelectedValue();int revision=++selectionRevision;if(row==null)return;category.setText(row.category);inspector.setText("Reading resolved rules…");
        clientThread.invokeLater(()->{if(!valid())return;loot.select(row.key);String text=loot.explain(row.key);SwingUtilities.invokeLater(()->{if(valid()&&revision==selectionRevision){inspector.setText(text);inspector.setCaretPosition(0);}});});
    }
    private void override(LootPreferences.Action action)
    {
        LootRow row=list.getSelectedValue();if(row==null||!valid())return;
        try{LootPreferences.ItemRule existing=preferences.snapshot().items.get(row.itemId);preferences.set(row.itemId,action!=null?action:existing==null?LootPreferences.Action.FILTER:existing.action,category.getText());
            if(action!=null)preferences.labelHidden(row.itemId,action==LootPreferences.Action.FILTER?null:action==LootPreferences.Action.HIDE);
            inspector.append("\nSaved. The next game tick refreshes this view.");}catch(IllegalArgumentException e){error(e);}
    }
    private void createRule(){LootRow row=list.getSelectedValue();if(row==null||!valid())return;if(editor!=null)editor.close();editor=new FilterEditor(icons);editor.seedName(row.name);editor.open(dialog);}
    private void source()
    {
        JOptionPane.showMessageDialog(dialog,"RuneLite 1.13.4 reports monster loot without ground-pile locations.\nThe source of a particular pile is unavailable, so monster-source filters are inactive.\nItem, value and ownership rules remain available; we never infer a source from nearby NPCs.");
    }
    private void wiki()
    {
        LootRow row=list.getSelectedValue();String name=JOptionPane.showInputDialog(dialog,"Monster / activity to look up on the OSRS Wiki. After reviewing Drops, use Create filter rule or the item search in Edit rules.",row!=null&&row.source!=null?row.source:"");
        if(name!=null&&!name.trim().isEmpty())LinkBrowser.browse(wikiUrl(name));
    }
    static String wikiUrl(String name){return "https://oldschool.runescape.wiki/w/"+URLEncoder.encode(name.trim().replace(' ','_'),StandardCharsets.UTF_8).replace("+","%20")+"#Drops";}
    private void error(Exception e){JOptionPane.showMessageDialog(dialog,e.getMessage(),"Not changed",JOptionPane.WARNING_MESSAGE);}
    static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    private static String title(String s){return s.charAt(0)+s.substring(1).toLowerCase(Locale.ROOT);}
    private static void button(JPanel p,String label,Runnable action){JButton b=new JButton(label);b.addActionListener(e->action.run());p.add(b);}
    void close(){closed=true;selectionRevision++;timer.stop();if(editor!=null)editor.close();if(dialog!=null)dialog.dispose();}
}

package com.improvedlooting;

import java.awt.*;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Locale;
import net.runelite.client.ui.FontManager;
import static com.improvedlooting.ImprovedLootingConfig.CardTheme;

/** The production single-row card renderer, also used for off-screen visual checks. */
final class LootCardPainter
{
    static final Color BACKGROUND=new Color(23,27,32,235),TEXT=new Color(236,239,243),VALUE=new Color(177,187,199);
    static Color background(CardTheme theme,Color chosen){return chosen!=null?chosen:theme==CardTheme.OSRS?new Color(55,44,28):BACKGROUND;}
    static Font font(CardTheme theme,int size,boolean bold)
    {
        if(theme==CardTheme.OSRS){Font base=bold?FontManager.getRunescapeBoldFont():FontManager.getRunescapeFont();return size==0?base:base.deriveFont((float)Math.max(8,Math.min(32,size)));}
        return new Font(Font.SANS_SERIF,bold?Font.BOLD:Font.PLAIN,size==0?12:Math.max(8,Math.min(32,size)));
    }
    static int height(CardTheme theme,FontMetrics metrics,int requestedHeight){return Math.max(metrics.getHeight()+(theme==CardTheme.OSRS?6:2),Math.max(0,Math.min(96,requestedHeight)));}
    static int iconSize(int height){return Math.max(1,height-2);}
    static int width(FontMetrics metrics,int iconSize,String name,long quantity,long price,boolean shortPrices,int seconds)
    {
        return iconSize+38+metrics.stringWidth(name+quantity(quantity))+metrics.stringWidth(details(price,shortPrices,seconds));
    }
    static String shortNumber(long value)
    {
        if(value<1000)return Long.toString(Math.max(0,value));
        double number=value;String[] suffix={"","k","m","b","t","q"};int unit=0;
        while(number>=999.95&&unit<suffix.length-1){number/=1000;unit++;}
        return String.format(Locale.ROOT,"%.1f",number).replaceAll("\\.0$","")+suffix[unit];
    }
    static double remaining(int firstSeen,int expiry,double now)
    {
        if(expiry<=0 || expiry==Integer.MAX_VALUE)return 1;
        if(expiry<=firstSeen)return now>=expiry?0:1;
        return Math.max(0,Math.min(1,(expiry-now)/(expiry-firstSeen)));
    }
    static String fit(String text,FontMetrics metrics,int width)
    {
        if(metrics.stringWidth(text)<=width)return text;
        String ellipsis="…";if(width<metrics.stringWidth(ellipsis))return "";
        int end=text.length();while(end>0&&metrics.stringWidth(text.substring(0,end)+ellipsis)>width)end--;
        return text.substring(0,end)+ellipsis;
    }
    static BufferedImage icon(BufferedImage original,int size,double remaining)
    { return icon(original,size,remaining,false); }
    static BufferedImage icon(BufferedImage original,int size,double remaining,boolean avoidEnlarging)
    {
        BufferedImage copy=new BufferedImage(size,size,BufferedImage.TYPE_INT_ARGB);if(original==null)return copy;
        Graphics2D g=copy.createGraphics();
        try{
            double scale=Math.min((double)size/original.getWidth(),(double)size/original.getHeight());if(avoidEnlarging)scale=Math.min(1,scale);int w=Math.max(1,(int)(original.getWidth()*scale)),h=Math.max(1,(int)(original.getHeight()*scale));
            g.drawImage(original,(size-w)/2,(size-h)/2,w,h,null);
            if(remaining<1){float feather=Math.max(2,size*.2f),front=(float)((1-Math.max(0,remaining))*(size+feather)-feather);
                g.setComposite(AlphaComposite.DstIn);g.setPaint(new LinearGradientPaint(0,front,0,front+feather,new float[]{0,1},new Color[]{new Color(255,255,255,0),Color.WHITE}));g.fillRect(0,0,size,size);}
        }finally{g.dispose();}return copy;
    }
    static String quantity(long quantity) { return quantity>1 ? " ("+String.format(Locale.ROOT,"%,d",quantity)+")" : ""; }
    static String details(long price,boolean shortPrices,int seconds)
    {
        return (price<=0?"":"("+(shortPrices?shortNumber(price):String.format(Locale.ROOT,"%,d",price))+" gp)")
            +(seconds<0?"":(price>0?" ":"")+"["+seconds+"s]");
    }
    static void surface(Graphics2D g,Rectangle bounds,boolean background,boolean border,int opacity,CardTheme theme,Color backgroundColor)
    {
        boolean osrs=theme==CardTheme.OSRS;
        if(background){Color color=background(theme,backgroundColor);g.setColor(new Color(color.getRed(),color.getGreen(),color.getBlue(),Math.round(Math.max(0,Math.min(100,opacity))*2.55f)));
            if(osrs)g.fillRect(bounds.x,bounds.y,bounds.width,bounds.height);else g.fillRoundRect(bounds.x,bounds.y,bounds.width,bounds.height,7,7);}
        if(border){g.setStroke(new BasicStroke(1));
            if(osrs){
                g.setColor(new Color(20,16,10,230));g.drawRect(bounds.x,bounds.y,bounds.width-1,bounds.height-1);
                g.setColor(new Color(155,130,81,230));g.drawLine(bounds.x+1,bounds.y+1,bounds.x+bounds.width-2,bounds.y+1);g.drawLine(bounds.x+1,bounds.y+1,bounds.x+1,bounds.y+bounds.height-2);
                g.setColor(new Color(90,69,41,230));g.drawLine(bounds.x+1,bounds.y+bounds.height-2,bounds.x+bounds.width-2,bounds.y+bounds.height-2);g.drawLine(bounds.x+bounds.width-2,bounds.y+1,bounds.x+bounds.width-2,bounds.y+bounds.height-2);
            }else{g.setColor(new Color(88,99,112,180));g.drawRoundRect(bounds.x,bounds.y,bounds.width-1,bounds.height-1,7,7);}
        }
    }
    static void row(Graphics2D original,Rectangle bounds,Paint rail,BufferedImage icon,String name,long quantity,long price,boolean hidden,boolean background,boolean border,int opacity,boolean shortPrices,int seconds,CardTheme theme,Color backgroundColor)
    {
        Graphics2D g=(Graphics2D)original.create();
        try{
            g.clip(bounds);
            boolean osrs=theme==CardTheme.OSRS;
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,osrs?RenderingHints.VALUE_ANTIALIAS_OFF:RenderingHints.VALUE_ANTIALIAS_ON);g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,osrs?RenderingHints.VALUE_TEXT_ANTIALIAS_OFF:RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            surface(g,bounds,background,border,opacity,theme,backgroundColor);
            Shape clip=g.getClip();if(!osrs)g.clip(new RoundRectangle2D.Double(bounds.x,bounds.y,bounds.width,bounds.height,7,7));g.setPaint(hidden?Color.GRAY:rail);
            int inset=osrs&&border?2:0;g.fillRect(bounds.x+inset,bounds.y+inset,osrs?3:4,bounds.height-inset*2);g.setClip(clip);
            int size=icon==null?18:icon.getWidth(),left=bounds.x+10;
            if(icon!=null)g.drawImage(icon,left,bounds.y+(bounds.height-size)/2,null);
            FontMetrics metrics=g.getFontMetrics();String amount=details(price,shortPrices,seconds);int amountX=bounds.x+bounds.width-9-metrics.stringWidth(amount);
            int nameX=left+size+7;String suffix=quantity(quantity);
            String label=fit(name,metrics,Math.max(0,amountX-nameX-12-metrics.stringWidth(suffix)))+suffix;
            int baseline=bounds.y+(bounds.height-metrics.getHeight())/2+metrics.getAscent();
            Shape textClip=g.getClip();g.clipRect(nameX,bounds.y,Math.max(0,amountX-nameX-8),bounds.height);
            if(osrs){g.setColor(Color.BLACK);g.drawString(label,nameX+1,baseline+1);}
            g.setPaint(hidden?Color.GRAY:rail);g.drawString(label,nameX,baseline);g.setClip(textClip);
            if(osrs){g.setColor(Color.BLACK);g.drawString(amount,amountX+1,baseline+1);}
            g.setPaint(hidden?Color.GRAY:rail);g.drawString(amount,amountX,baseline);
        }finally{g.dispose();}
    }
    static Rectangle place(int anchorX,int anchorY,int width,int height,Rectangle viewport,java.util.List<Rectangle> occupied)
    {
        if(width>viewport.width || height>viewport.height)return null;
        int x=Math.max(viewport.x,Math.min(anchorX-width/2,viewport.x+viewport.width-width));
        int y=Math.max(viewport.y,Math.min(anchorY-height,viewport.y+viewport.height-height));
        Rectangle candidate=new Rectangle(x,y,width,height);
        for(int tries=0;tries<32;tries++){
            Rectangle hit=null;for(Rectangle box:occupied)if(candidate.intersects(box)){hit=box;break;}
            if(hit==null)return candidate;
            int above=hit.y-height-3;
            if(above>=viewport.y)candidate.y=above;
            else {candidate.x=hit.x+hit.width+4;candidate.y=y;if(candidate.x+width>viewport.x+viewport.width){candidate.x=hit.x-width-4;if(candidate.x<viewport.x)return null;}}
        }return null;
    }
}

package com.improvedlooting;

import java.awt.*;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.FontManager;

final class LootCardsOverlay extends Overlay
{
    private final LootAlerts alerts;
    private final ImprovedLootingConfig config;
    @Inject LootCardsOverlay(LootAlerts alerts, ImprovedLootingConfig config)
    { this.alerts = alerts; this.config = config; setPosition(OverlayPosition.BOTTOM_RIGHT); setLayer(OverlayLayer.ABOVE_WIDGETS); }
    @Override public Dimension render(Graphics2D graphics)
    {
        if (!config.notificationCards()) return null;
        java.util.List<LootAlerts.Card> cards = alerts.cards(); if (cards.isEmpty()) return null;
        Graphics2D g = (Graphics2D)graphics.create(); int y = 0;
        try
        {
            g.setFont(FontManager.getRunescapeSmallFont());
            for (LootAlerts.Card card : cards)
            {
                g.setColor(new Color(25, 28, 32, 220)); g.fillRoundRect(0, y, 260, 30, 8, 8);
                g.setColor(new Color(231, 181, 70)); String text = card.text;
                while (text.length() > 1 && g.getFontMetrics().stringWidth(text) > 242) text = text.substring(0, text.length() - 1);
                g.drawString(text, 8, y + 20); y += 34;
            }
        }
        finally { g.dispose(); }
        return new Dimension(260, y);
    }
}

package com.improvedlooting;

import java.awt.Color;
import net.runelite.api.TileItem;

/** One set of label decisions for both cards and plain labels. */
final class LootDisplayOptions
{
    static boolean detail(ImprovedLootingConfig.DetailMode mode,boolean rule)
    { return mode==ImprovedLootingConfig.DetailMode.ALWAYS || mode==ImprovedLootingConfig.DetailMode.RULES && rule; }
    static long price(ImprovedLootingConfig config,GroundLoot.Entry entry)
    { return !config.lootCompact() && detail(config.priceDisplay(),entry.display.isShowValue()) ? PriceTiers.value(entry.facts.getGePrice(),entry.renderQuantity):0; }
    static int seconds(ImprovedLootingConfig config,GroundLoot.Entry entry,int tick)
    { return !config.lootCompact() && detail(config.timerDisplay(),entry.display.isShowDespawn()) && entry.renderDespawn>0 && entry.renderDespawn<Integer.MAX_VALUE ? LootResolution.secondsRemaining(entry.renderDespawn,tick):-1; }
    static boolean hidden(boolean ruleHidden,Boolean manual,long price,int minimum)
    { return manual!=null?manual:ruleHidden || price<Math.max(0,minimum); }
    static boolean untradeable(GroundLoot.Entry entry)
    { return entry.facts != null && !entry.facts.isTradeable(); }
    static int minimum(ImprovedLootingConfig config,GroundLoot.Entry entry)
    { return config.keepUntradeablesVisible() && untradeable(entry) ? 0 : config.minimumLabelValue(); }
    static boolean ownershipHidden(ImprovedLootingConfig config,GroundLoot.Entry entry)
    {
        int ownership=entry.item.getOwnership();
        return config.onlyShowOwnedDrops() && ownership!=TileItem.OWNERSHIP_SELF && ownership!=TileItem.OWNERSHIP_GROUP;
    }
    static Color color(ImprovedLootingConfig config,GroundLoot.Entry entry,Color tierColor)
    {
        Color filter=entry.display.getTextColor();
        if(!Color.WHITE.equals(filter))return filter;
        if(untradeable(entry))return config.untradeableColor()==null?new Color(0xff5555):config.untradeableColor();
        return tierColor;
    }
    static boolean tierEffects(ImprovedLootingConfig config,GroundLoot.Entry entry)
    { return config.priceTiersEnabled() && !untradeable(entry); }
    private LootDisplayOptions() {}
}

package com.improvedlooting;

import java.util.*;
import java.util.regex.*;

/** Conservative format reader, not a replacement for Loot Filters' evaluator. */
final class LootIconImport
{
    static List<ItemIcons.Assignment> parse(String source)
    {
        if(source.length()>1000000) { throw new IllegalArgumentException("Filter is too large."); }
        // Remove comments without treating comment markers inside strings as comments.
        String clean=source;
        StringBuilder stripped=new StringBuilder();
        boolean quote=false;
        for(int i=0;i<clean.length();i++)
        {
            char c=clean.charAt(i);
            if(c=='"' && (i==0 || clean.charAt(i-1)!='\\')) { quote=!quote; }
            if(!quote && c=='/' && i+1<clean.length() && clean.charAt(i+1)=='/') { while(i<clean.length() && clean.charAt(i)!='\n') { i++; } stripped.append('\n'); continue; }
            if(!quote && c=='/' && i+1<clean.length() && clean.charAt(i+1)=='*') { int end=clean.indexOf("*/",i+2); if(end<0) { throw new IllegalArgumentException("Unclosed comment."); } i=end+1; continue; }
            stripped.append(c);
        }
        clean=stripped.toString();
        if(Pattern.compile("(?m)^\\s*#").matcher(clean).find()) { throw new IllegalArgumentException("This filter uses directives/macros. Automatic icon import is not supported; assign its icons manually. Nothing was changed."); }
        Pattern block=Pattern.compile("\\G\\s*(meta|rule|if|apply)\\s*(?:\\(([^{}]*)\\))?\\s*\\{([^{}]*)\\}");
        Matcher m=block.matcher(clean); int end=0;
        LinkedHashMap<String,ItemIcons.Assignment> result=new LinkedHashMap<>();
        while(m.find())
        {
            end=m.end();
            if(m.group(1).equals("meta")) { continue; }
            if(m.group(1).equals("apply")) { throw unsupported(); }
            String condition=m.group(2);
            if(condition==null) { throw unsupported(); }
            Matcher selector=Pattern.compile("\\s*(id|name)\\s*:\\s*(.*?)\\s*",Pattern.DOTALL).matcher(condition);
            if(!selector.matches()) { throw unsupported(); }
            String values=selector.group(2).trim();
            if(values.startsWith("[") && values.endsWith("]")) { values=values.substring(1,values.length()-1); }
            List<String> keys=new ArrayList<>();
            Matcher value=Pattern.compile(selector.group(1).equals("id") ? "\\G\\s*(\\d+)\\s*(?:,|$)" : "\\G\\s*\"([^\"*?\\\\]+)\"\\s*(?:,|$)").matcher(values);
            int used=0;
            while(value.find()) { keys.add(value.group(1)); used=value.end(); }
            if(keys.isEmpty() || used!=values.length()) { throw unsupported(); }
            Matcher icon=Pattern.compile("(?:^|(?<=;))\\s*icon\\s*=\\s*(CurrentItem|Item|Sprite)\\s*\\(([^()]*)\\)\\s*;",Pattern.DOTALL).matcher(m.group(3));
            if(!icon.find()) { throw new IllegalArgumentException("Every rule must have an explicit CurrentItem(), Item(id), or Sprite(id,index) icon. File icons and rules without icons cannot be transferred safely."); }
            String type=icon.group(1), args=icon.group(2).trim();
            int iconId=0,index=0;
            if(type.equals("CurrentItem")) { if(!args.isEmpty()) { throw unsupported(); } }
            else
            {
                if(!args.matches(type.equals("Item") ? "\\d+" : "\\d+\\s*,\\s*\\d+")) { throw unsupported(); }
                String[] parts=args.split("\\s*,\\s*");
                try { iconId=Integer.parseInt(parts[0]); if(parts.length>1) { index=Integer.parseInt(parts[1]); } }
                catch(NumberFormatException e) { throw unsupported(); }
            }
            if(icon.find()) { throw new IllegalArgumentException("Multiple icon assignments in a rule are not supported."); }
            for(String key:keys)
            {
                ItemIcons.Assignment a=new ItemIcons.Assignment();
                try { if(selector.group(1).equals("id")) { a.itemId=Integer.parseInt(key); } else { a.name=key; } }
                catch(NumberFormatException e) { throw unsupported(); }
                a.kind=type.equals("CurrentItem") ? ItemIcons.Kind.CURRENT_ITEM : type.equals("Item") ? ItemIcons.Kind.ITEM : ItemIcons.Kind.SPRITE;
                a.iconId=iconId; a.spriteIndex=index;
                if(a.itemId>100000 || iconId>100000 || index>255 || result.size()>=500) { throw unsupported(); }
                // Terminal rules use the first match. Mixed name/id selectors can overlap.
                if(!result.isEmpty() && result.values().iterator().next().itemId>=0 != (a.itemId>=0)) { throw new IllegalArgumentException("Mixed name and ID rules need manual review; nothing was imported."); }
                result.putIfAbsent(a.key(),a);
            }
        }
        if(!clean.substring(end).trim().isEmpty() || result.isEmpty()) { throw unsupported(); }
        return new ArrayList<>(result.values());
    }
    private static IllegalArgumentException unsupported()
    { return new IllegalArgumentException("Only terminal rules with exact item IDs or names are supported. Conditional, wildcard, inherited or malformed rules require manual assignments. Nothing was changed."); }
}

package com.improvedlooting;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;

/** User Alt-clicks edit only this plugin's label preferences; never game actions. */
@Singleton
final class LootLabelInput extends MouseAdapter
{
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject GroundLoot loot;
    @Inject LootPreferences preferences;
    private volatile List<Hit> hits=Collections.emptyList();
    private final List<Hit> frame=new ArrayList<>();
    private volatile long generation, renderedAt;
    private volatile boolean active;
    private long frameGeneration;
    private Hit pressed;
    private int pressX,pressY;
    private long pressGeneration;
    private boolean consumeClick;

    void start(){active=true;reset();}
    void stop(){active=false;reset();}
    void reset(){generation++;hits=Collections.emptyList();}
    void beginFrame(){frameGeneration=generation;frame.clear();hits=Collections.emptyList();}
    void add(Rectangle bounds,GroundLoot.Entry entry,boolean hidden){frame.add(new Hit(bounds,entry.item.getId(),hidden));}
    void finishFrame(){if(active && frameGeneration==generation){renderedAt=System.nanoTime();hits=Collections.unmodifiableList(new ArrayList<>(frame));}}

    @Override public MouseEvent mousePressed(MouseEvent event)
    {
        pressed=null;consumeClick=false;
        if(!active || event.isConsumed() || event.getButton()!=MouseEvent.BUTTON1 || !event.isAltDown()
            || System.nanoTime()-renderedAt>500_000_000L)return event;
        for(Hit hit:hits)if(hit.bounds.contains(event.getPoint())) {
            pressed=hit;pressX=event.getX();pressY=event.getY();pressGeneration=generation;
            consumeClick=true;event.consume();break;
        }
        return event;
    }
    @Override public MouseEvent mouseReleased(MouseEvent event)
    {
        if(!consumeClick || event.getButton()!=MouseEvent.BUTTON1)return event;
        event.consume();Hit hit=pressed;pressed=null;long token=pressGeneration;
        if(hit!=null && Math.abs(event.getX()-pressX)<=5 && Math.abs(event.getY()-pressY)<=5)
            thread.invokeLater(()->{
                if(active && token==generation && loot.groundAllowed() && client.getGameState()==GameState.LOGGED_IN && !client.isMenuOpen()) {
                    preferences.labelHidden(hit.id,!hit.hidden);
                    reset();
                }
            });
        return event;
    }
    @Override public MouseEvent mouseClicked(MouseEvent event)
    {
        if(consumeClick && event.getButton()==MouseEvent.BUTTON1){event.consume();consumeClick=false;}
        return event;
    }
    private static final class Hit {
        final Rectangle bounds;final int id;final boolean hidden;
        Hit(Rectangle bounds,int id,boolean hidden){this.bounds=new Rectangle(bounds);this.id=id;this.hidden=hidden;}
    }
}

package com.improvedlooting;

import com.google.gson.Gson;
import com.improvedlooting.rs2f.DisplayConfig;
import java.awt.Color;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/** Explicit user overrides, separate from imported RS2F source. */
@Singleton
final class LootPreferences
{
    static final String KEY = "lootOverridesV1";
    enum Action { FILTER, SHOW, HIDE, HIGHLIGHT }
    static final class ItemRule { Action action = Action.FILTER; String category = ""; Boolean labelHidden; }
    static final class Data
    {
        int version = 1;
        Map<Integer, ItemRule> items = new LinkedHashMap<>();
        Map<String, Action> sources = new LinkedHashMap<>();
    }
    @Inject ConfigManager configs;
    @Inject Gson gson;
    private String loaded;
    private Data current = new Data();
    private long revision;
    synchronized Data snapshot()
    {
        String raw = configs.getConfiguration(ImprovedLootingConfig.GROUP, KEY);
        if (!Objects.equals(raw, loaded))
        {
            loaded = raw;
            try { current = parse(raw); } catch (IllegalArgumentException ex) { current = new Data(); }
            revision++;
        }
        return current;
    }
    synchronized long revision() { snapshot(); return revision; }
    Data parse(String raw)
    {
        if (raw == null || raw.isBlank()) return new Data();
        if (raw.length() > 150000) throw new IllegalArgumentException("Too many overrides");
        try
        {
            Data data = gson.fromJson(raw, Data.class);
            if (data == null || data.version != 1 || data.items == null || data.sources == null
                || data.items.size() > 512 || data.sources.size() > 100) throw new IllegalArgumentException("Invalid overrides");
            data.items.forEach((id, rule) -> {
                if (id == null || id < 0 || id > 100000 || rule == null || rule.action == null || !validLabel(rule.category, 40))
                    throw new IllegalArgumentException("Invalid item override");
            });
            data.sources.forEach((name, action) -> {
                if (!validLabel(name, 100) || name.isBlank() || action == null) throw new IllegalArgumentException("Invalid source rule");
            });
            return data;
        }
        catch (com.google.gson.JsonParseException ex) { throw new IllegalArgumentException("Invalid overrides", ex); }
    }
    static boolean validLabel(String text, int limit)
    { return text != null && text.length() <= limit && text.chars().noneMatch(c -> Character.isISOControl(c) || c == '<' || c == '>'); }
    synchronized void set(int id, Action action, String category)
    {
        Data next = parse(gson.toJson(snapshot()));
        ItemRule rule = next.items.getOrDefault(id,new ItemRule()); rule.action = action; rule.category = category.trim();
        if (action == Action.FILTER && rule.category.isEmpty() && rule.labelHidden==null) next.items.remove(id); else next.items.put(id, rule);
        save(next);
    }
    synchronized void labelHidden(int id,Boolean value)
    {
        Data next=parse(gson.toJson(snapshot()));ItemRule rule=next.items.getOrDefault(id,new ItemRule());
        rule.labelHidden=value;
        if(rule.action==Action.FILTER && rule.category.isEmpty() && value==null)next.items.remove(id);else next.items.put(id,rule);
        save(next);
    }
    Boolean labelHidden(int id){ItemRule rule=snapshot().items.get(id);return rule==null?null:rule.labelHidden;}
    synchronized void source(String name, Action action)
    {
        Data next = parse(gson.toJson(snapshot()));
        name = name.trim();
        if (action == Action.FILTER) next.sources.remove(name); else next.sources.put(name, action);
        save(next);
    }
    private void save(Data next)
    {
        String raw = gson.toJson(next); parse(raw);
        current = next; loaded = raw; revision++;
        configs.setConfiguration(ImprovedLootingConfig.GROUP, KEY, raw);
    }
    String category(int id) { ItemRule rule = snapshot().items.get(id); return rule == null ? "" : rule.category; }
    Action action(int id, String source)
    {
        Data data = snapshot(); ItemRule rule = data.items.get(id);
        if (rule != null && rule.action != Action.FILTER) return rule.action;
        return source == null ? Action.FILTER : data.sources.getOrDefault(source, Action.FILTER);
    }
    static DisplayConfig apply(DisplayConfig display, Action action)
    {
        switch (action)
        {
            case HIDE: return display.toBuilder().hidden(true).hideOverlay(true).build();
            case SHOW: return display.toBuilder().hidden(false).hideOverlay(false).build();
            case HIGHLIGHT: return display.toBuilder().hidden(false).hideOverlay(false).textColor(Color.YELLOW)
                .highlightTile(true).tileStrokeColor(Color.YELLOW).tileFillColor(new Color(255, 220, 0, 30))
                .showLootbeam(true).lootbeamColor(Color.YELLOW).build();
            default: return display;
        }
    }
}

package com.improvedlooting;

import java.util.*;
import javax.inject.*;

/** Validated, versioned copies of this plugin's settings only. Assets travel inside the backup. */
@Singleton
final class LootProfiles
{
    static final String SAVED="savedLootPresetsV1", UNDO="lootSetupUndoV1";
    static final String[] BOOLEAN_KEYS={"lootOverlay","lootBeams","lootCompact","lootReveal","priceTiersEnabled","shareMenuIcons","lootNotifications","lootSounds","originalImages","alwaysShowValue","alwaysShowTimer","groupStacks","despawnWarnings","notificationCards","iconDespawnFade","cardBackground","cardBorder","cardShortPrices","cardAutoWidth","keepUntradeablesVisible","onlyShowOwnedDrops"};
    static final Map<String,int[]> NUMBERS=new LinkedHashMap<>();
    static { NUMBERS.put("labelRange",new int[]{1,64});NUMBERS.put("maxLabels",new int[]{10,1000});NUMBERS.put("labelSpacing",new int[]{0,16});NUMBERS.put("labelFontSize",new int[]{0,32});NUMBERS.put("iconSize",new int[]{12,96});NUMBERS.put("despawnSeconds",new int[]{1,120});NUMBERS.put("despawnMinimum",new int[]{0,Integer.MAX_VALUE});NUMBERS.put("alertVolume",new int[]{0,100});NUMBERS.put("soundCooldown",new int[]{0,60}); }
    static final class Setup { int version=1;Map<String,String> settings=new LinkedHashMap<>(); }
    static { NUMBERS.put("minimumLabelValue",new int[]{0,Integer.MAX_VALUE});NUMBERS.put("cardWidth",new int[]{120,2048});NUMBERS.put("cardHeight",new int[]{0,96});NUMBERS.put("cardRows",new int[]{0,20});NUMBERS.put("cardOpacity",new int[]{0,100}); }
    static final class Library { int version=1;Map<String,Setup> presets=new LinkedHashMap<>(); }
    @Inject ItemIcons icons;
    @Inject LootPreferences preferences;
    static Set<String> keys(){Set<String> keys=new LinkedHashSet<>(Arrays.asList(BOOLEAN_KEYS));keys.addAll(NUMBERS.keySet());Collections.addAll(keys,"cardTheme","cardBackgroundColor","untradeableColor","priceDisplay","timerDisplay","groundStyle","labelOrder","labelAlignment",FilterIcons.KEY,ItemIcons.KEY,PriceTiers.KEY,LootPreferences.KEY);return keys;}
    Setup capture(){Setup s=new Setup();for(String key:keys())s.settings.put(key,icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,key));return s;}
    String export(){return icons.gson.toJson(capture());}
    Setup parse(String raw)
    {
        if(raw==null||raw.length()>24000000)throw new IllegalArgumentException("Setup exceeds 24 MB");
        try{Setup setup=icons.gson.fromJson(raw,Setup.class);validate(setup);return setup;}
        catch(com.google.gson.JsonParseException e){throw new IllegalArgumentException("Invalid setup backup",e);}
    }
    void validate(Setup s)
    {
        if(s==null||s.version!=1||s.settings==null||!keys().containsAll(s.settings.keySet()))throw new IllegalArgumentException("Unsupported setup or setting");
        for(Map.Entry<String,String> e:s.settings.entrySet())
        {
            String key=e.getKey(),value=e.getValue();if(value==null)continue;
            if(Arrays.asList(BOOLEAN_KEYS).contains(key)&&!value.equals("true")&&!value.equals("false"))throw new IllegalArgumentException("Invalid switch: "+key);
            if(NUMBERS.containsKey(key)){try{int n=Integer.parseInt(value);int[] bounds=NUMBERS.get(key);if(n<bounds[0]||n>bounds[1]||key.equals("labelFontSize")&&n>0&&n<8)throw new NumberFormatException();}catch(NumberFormatException ex){throw new IllegalArgumentException("Out of range: "+key);}}
            if(key.equals("labelOrder"))ImprovedLootingConfig.LabelOrder.valueOf(value);
            if(key.equals("priceDisplay") || key.equals("timerDisplay"))ImprovedLootingConfig.DetailMode.valueOf(value);
            if(key.equals("cardTheme"))ImprovedLootingConfig.CardTheme.valueOf(value);
            if(key.equals("cardBackgroundColor") || key.equals("untradeableColor")){
                try{Integer.parseInt(value);}catch(NumberFormatException ex){throw new IllegalArgumentException("Invalid color: "+key,ex);}
            }
            if(key.equals("groundStyle"))ImprovedLootingConfig.GroundStyle.valueOf(value);
            if(key.equals("labelAlignment"))ImprovedLootingConfig.LabelAlignment.valueOf(value);
            if(key.equals(FilterIcons.KEY)&&!value.isBlank())icons.filters.parse(value);
            if(key.equals(ItemIcons.KEY)&&!value.isBlank())icons.parse(value);
            if(key.equals(PriceTiers.KEY))icons.tiers.parse(value);
            if(key.equals(LootPreferences.KEY))preferences.parse(value);
        }
    }
    void applyValidated(Setup s,Object expectedProfile,String expectedCurrent)
    {
        if(!Objects.equals(expectedProfile,icons.configs.getProfile())||!Objects.equals(expectedCurrent,export()))throw new IllegalArgumentException("Profile or settings changed. Preview the setup again.");
        icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,UNDO,expectedCurrent);
        for(String key:keys()){String value=s.settings.get(key);if(value==null)icons.configs.unsetConfiguration(ImprovedLootingConfig.GROUP,key);else icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,key,value);}
    }
    String undo(){return icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,UNDO);}
    Library library()
    {
        String raw=icons.configs.getConfiguration(ImprovedLootingConfig.GROUP,SAVED);if(raw==null||raw.isBlank())return new Library();
        if(raw.length()>24000000)throw new IllegalArgumentException("Preset library exceeds 24 MB");
        try{Library l=icons.gson.fromJson(raw,Library.class);if(l==null||l.version!=1||l.presets==null||l.presets.size()>12)throw new IllegalArgumentException("Invalid preset library");for(String name:l.presets.keySet())if(!LootPreferences.validLabel(name,60)||name.isBlank())throw new IllegalArgumentException("Invalid preset name");return l;}catch(com.google.gson.JsonParseException e){throw new IllegalArgumentException("Invalid preset library",e);}
    }
    void save(String name){name=name.trim();if(!LootPreferences.validLabel(name,60)||name.isBlank())throw new IllegalArgumentException("Use a name of 1–60 characters");Library l=library();l.presets.put(name,capture());persist(l);}
    void remove(String name){Library l=library();l.presets.remove(name);persist(l);}
    private void persist(Library l){String raw=icons.gson.toJson(l);if(raw.length()>24000000||l.presets.size()>12)throw new IllegalArgumentException("Keep at most 12 presets and 24 MB total");icons.configs.setConfiguration(ImprovedLootingConfig.GROUP,SAVED,raw);}
    String starter(boolean valuable)
    {
        Setup s=capture();FilterIcons.Bundle b=new FilterIcons.Bundle();b.compressedSource=FilterIcons.compress(valuable?
            "rule(gevalue:>=100000) {textColor=\"#ffcf60\"; icon=CurrentItem(); showValue=true; showDespawn=true; showLootbeam=true; notify=true;}\nrule(gevalue:>=1000) {showValue=true; showDespawn=true;}\nrule(true) {hideOverlay=true;}":
            "apply(true) {showValue=true; showDespawn=true; icon=CurrentItem();}\nrule(gevalue:>=100000) {textColor=\"#ffcf60\"; showLootbeam=true;}");
        s.settings.put(FilterIcons.KEY,icons.gson.toJson(b));s.settings.put(LootPreferences.KEY,null);return icons.gson.toJson(s);
    }
    String groundItemsPreview()
    {
        String highlights=icons.configs.getConfiguration("grounditems","highlightedItems"),hidden=icons.configs.getConfiguration("grounditems","hiddenItems");
        if((highlights==null||highlights.isBlank())&&(hidden==null||hidden.isBlank()))throw new IllegalArgumentException("No Ground Items highlight / hide lists found in this profile");
        StringBuilder rules=new StringBuilder("apply(true) {showValue=true; showDespawn=true;}\n");
        appendNames(rules,highlights,"hidden=false; hideOverlay=false; textColor=\"#ffcf60\"; showLootbeam=true;");
        appendNames(rules,hidden,"hidden=true; hideOverlay=true;");
        Setup s=capture();FilterIcons.Bundle bundle=new FilterIcons.Bundle();bundle.compressedSource=FilterIcons.compress(rules.toString());s.settings.put(FilterIcons.KEY,icons.gson.toJson(bundle));return icons.gson.toJson(s);
    }
    private static void appendNames(StringBuilder rules,String names,String display)
    {
        if(names==null)return;if(names.length()>100000)throw new IllegalArgumentException("Item list too large");
        for(String name:names.split(",")){name=name.trim();if(name.isEmpty())continue;FilterEditor.rule(name,0,0);rules.append("rule(name:\"").append(name).append("\") {").append(display).append("}\n");}
    }
}

package com.improvedlooting;

import java.awt.*;
import javax.swing.*;

final class LootProfilesEditor
{
    private final LootProfiles profiles;
    private final JTextArea text=new JTextArea();
    private final JComboBox<String> saved=new JComboBox<>();
    private final JLabel status=new JLabel("Export / paste a complete setup, then validate and apply. Current settings are saved for Undo.");
    private JDialog dialog;
    private volatile boolean closed;
    private final Object profile;
    private int revision;
    LootProfilesEditor(LootProfiles profiles){this.profiles=profiles;profile=profiles.icons.configs.getProfile();}
    void open(Component owner)
    {
        JPanel root=new JPanel(new BorderLayout(8,8));root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
        JPanel actions=new JPanel(new GridLayout(0,3,6,6));actions.add(saved);
        button(actions,"Save current preset",()->{String name=JOptionPane.showInputDialog(dialog,"Preset name");if(name!=null){profiles.save(name);refresh();}});
        button(actions,"Load preset preview",()->{String name=(String)saved.getSelectedItem();if(name!=null)text.setText(profiles.icons.gson.toJson(profiles.library().presets.get(name)));});
        button(actions,"Delete saved preset",()->{String name=(String)saved.getSelectedItem();if(name!=null&&JOptionPane.showConfirmDialog(dialog,"Delete saved preset “"+name+"”? Current settings are retained.","Delete preset",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){profiles.remove(name);refresh();}});
        button(actions,"Export current setup",()->text.setText(profiles.export()));button(actions,"Apply pasted setup",()->apply(text.getText()));
        button(actions,"Preview visible starter",()->text.setText(profiles.starter(false)));button(actions,"Preview valuable starter",()->text.setText(profiles.starter(true)));
        button(actions,"Undo last setup change",()->{String before=profiles.undo();if(before==null)throw new IllegalArgumentException("No setup change to undo");apply(before);});
        button(actions,"Copy Ground Items lists",()->{text.setText(profiles.groundItemsPreview());status.setText("Preview: hide / highlight names only. Apply replaces our filter; original Ground Items settings are untouched.");});
        root.add(actions,BorderLayout.NORTH);text.setLineWrap(true);text.setWrapStyleWord(true);root.add(new JScrollPane(text),BorderLayout.CENTER);root.add(status,BorderLayout.SOUTH);refresh();
        dialog=new JDialog(SwingUtilities.getWindowAncestor(owner),"Presets and backups — Improved Looting",Dialog.ModalityType.MODELESS);dialog.setContentPane(root);dialog.setSize(850,580);dialog.setLocationRelativeTo(owner);dialog.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){close();}});dialog.setVisible(true);
    }
    private boolean valid(){return !closed&&java.util.Objects.equals(profile,profiles.icons.configs.getProfile());}
    private void apply(String raw)
    {
        if(!valid())return;String before=profiles.export();int token=++revision;status.setText("Checking settings, filter, images and sounds…");
        new SwingWorker<LootProfiles.Setup,Void>(){protected LootProfiles.Setup doInBackground(){return profiles.parse(raw);}protected void done(){if(!valid()||token!=revision)return;try{profiles.applyValidated(get(),profile,before);status.setText("Setup applied. Undo restores the complete previous setup.");}catch(Exception e){error(e);}}}.execute();
    }
    private void refresh(){saved.removeAllItems();for(String name:profiles.library().presets.keySet())saved.addItem(name);}
    private void button(JPanel p,String label,Runnable action){JButton b=new JButton(label);b.addActionListener(e->{if(!valid())return;try{action.run();}catch(Exception ex){error(ex);}});p.add(b);}
    private void error(Exception e){Throwable cause=e.getCause()==null?e:e.getCause();status.setText("Not changed: "+cause.getMessage());}
    void close(){closed=true;revision++;if(dialog!=null)dialog.dispose();}
}

package com.improvedlooting;

import com.improvedlooting.rs2f.DisplayConfig;
import com.improvedlooting.rs2f.FilterRule;
import com.improvedlooting.rs2f.model.ItemFacts;
import java.util.*;

/** Shared decisions and explanations; callers capture game facts on the client thread. */
final class LootResolution
{
    static DisplayConfig resolve(FilterIcons.Prepared filter, ItemFacts facts, LootPreferences preferences, String source)
    {
        DisplayConfig display = filter.program.evaluate(facts);
        return preferences == null ? display : LootPreferences.apply(display, preferences.action(facts.getId(), source));
    }
    static int secondsRemaining(int despawnTick, int currentTick)
    { return despawnTick <= 0 ? -1 : (int)Math.max(0, (((long)despawnTick - currentTick) * 3 + 4) / 5); }
    static String explain(FilterIcons.Prepared filter, ItemFacts facts, DisplayConfig finalDisplay,
        LootPreferences.Action override, String source, int seconds)
    {
        StringBuilder out = new StringBuilder();
        out.append(facts.getName()).append(" (#").append(facts.getId()).append(")\n")
            .append("Quantity: ").append(facts.getQuantity()).append("\nStack GE value: ")
            .append(PriceTiers.value(facts.getGePrice(), facts.getQuantity())).append(" gp\n")
            .append("Ownership: ").append(ownership(facts.getOwnership())).append("\n")
            .append("Source: ").append(source == null ? "Unavailable: RuneLite does not identify each pile’s monster source" : source + " (server loot event)").append("\n")
            .append("Despawn: ").append(seconds < 0 ? "Unknown; not supplied by client" : seconds + " seconds").append("\n\nRule evaluation, highest priority first:\n");
        int index = 0, matched = 0;
        for (FilterRule rule : filter.program.rules)
        {
            index++;
            if (!rule.getCond().test(null, facts)) continue;
            matched++;
            out.append('#').append(index).append(" matched, source line ").append(filter.userLine(rule.getSourceLine()))
                .append(rule.isTerminal() ? " — final matching rule\n" : " — apply and continue\n");
            if (rule.isTerminal()) break;
            if (matched >= 100) { out.append("Further matching rules omitted from this explanation.\n"); break; }
        }
        if (matched == 0) out.append("No matching rule; default visible white label.\n");
        out.append("\nManual/source override: ").append(override).append("\nFinal result:\n")
            .append("Label: ").append(finalDisplay.isHideOverlay() ? "hidden" : "visible")
            .append("\nHidden item rule: ").append(finalDisplay.isHidden())
            .append("\nColor: ").append(String.format("#%06X", finalDisplay.getTextColor().getRGB() & 0xffffff))
            .append("\nIcon: ").append(finalDisplay.getIcon() == null ? "none" : finalDisplay.getIcon())
            .append("\nBeam rule: ").append(finalDisplay.isShowLootbeam())
            .append("\nNotification rule: ").append(finalDisplay.isNotify())
            .append("\nSound rule: ").append(finalDisplay.getSound() == null ? "silent" : finalDisplay.getSound())
            .append("\nMenu priority: ").append(finalDisplay.getMenuSort())
            .append("\n\nAppearance, tier beam settings, seven-tier effects and master alert switches also apply. Hidden drops never alert.\n");
        return out.toString();
    }
    private static String ownership(int value)
    {
        switch (value) { case 1: return "Yours"; case 2: return "Other player"; case 3: return "Group"; default: return "Public/unassigned"; }
    }
    private LootResolution() { }
}

