    @Test public void normalClicksMissesAndAltDragsDoNotEditPreferences()
    {
        Fixture f=new Fixture();f.frame(false);f.gesture(false,30,30);f.gesture(true,300,300);f.flush();assertNull(f.input.preferences.labelHidden(1));
